    if (/平均下单|cost per|per order|\bcpc\b|\bcpa\b|\bcpm\b|出价|budget(?!.*spent)/i.test(t)) {
      if (!/^(成本|花费|消耗|cost|spend|广告花费|广告成本)$/i.test(t)) {
