    const order = ['planStatus', 'roi', 'spend', 'orders', 'revenue', 'campaign'];
    for (const field of order) {
      if (!HEADER_ALIASES[field]) continue;
      for (const a of HEADER_ALIASES[field]) {
        const al = a.toLowerCase();
        if (!(t === al || t.includes(al) || (al.length >= 2 && al.includes(t)))) {
          continue;
        }
        if (field === 'planStatus') {
          if (/投放状态|计划状态|delivery|operation status/.test(t)) return field;
          if (t === al || t === '开关' || t === 'switch' || t === 'enable' || t === 'enabled') {
            return field;
          }
          if (/开关|switch|toggle|on\/off/.test(t) && t.length <= 12) return field;
          continue;
        }
        if (field === 'spend') {
          if (/平均下单|cost per|per order|\bcpc\b|\bcpa\b|\bcpm\b/.test(t)) continue;
          if (
            t.includes('budget') &&
            !t.includes('spent') &&
            !t.includes('spend') &&
            !t.includes('cost') &&
            !t.includes('成本')
          ) {
            continue;
          }
        }
        // 「名称」太宽，要求更像广告系列
        if (field === 'campaign' && (al === '名称' || al === 'name')) {
          if (
            !/系列|campaign|广告|活动|product|品名|计划/.test(t) &&
            t !== '名称' &&
            t !== 'name'
          ) {
            continue;
          }
        }
        // 「sales」勿抢销量列以外的无关列
        if (field === 'revenue' && al === 'sales' && /order|unit|sku|销量|订单/.test(t)) {
          continue;
        }
        return field;
      }
    }
    return null;
  }

  function extractTableHeaders(table) {
    let headerRow = table.querySelector('thead tr') || table.querySelector('tr');
    if (!headerRow) return { fields: [] };
    const cells = [...headerRow.querySelectorAll('th, td')];
    return {
      fields: cells.map((c) => matchHeaderField(c.innerText || c.textContent || ''))
    };
  }

  function parseHtmlTable(table) {
    const { fields } = extractTableHeaders(table);
    if (!fields.some(Boolean)) return [];
    let switchColIndex = fields.indexOf('planStatus');
    if (switchColIndex < 0) switchColIndex = null;
    const bodyRows = table.querySelectorAll('tbody tr');
    const rows = bodyRows.length
      ? [...bodyRows]
      : [...table.querySelectorAll('tr')].slice(1);
    const results = [];
    for (const tr of rows) {
      const cells = [...tr.querySelectorAll('td, th')];
      if (!cells.length) continue;
      const row = {};
      fields.forEach((field, i) => {
        if (!field || !cells[i]) return;
        if (field === 'planStatus') {
          row.planStatus = parseSwitchFromEl(cells[i]) || 'unknown';
          return;
        }
        row[field] = cleanText(cells[i].innerText || cells[i].textContent || '');
      });
      if (!row.planStatus) {
        row.planStatus = detectPlanStatusFromRow(tr, cells, switchColIndex);
      }
      if (Object.keys(row).length) results.push(row);
    }
    return results;
  }

  function parseRoleTable(root) {
    const headerCells = [
      ...root.querySelectorAll(
        '[role="columnheader"], .ant-table-thead th, [class*="table-header"] th'
      )
    ];
    if (!headerCells.length) return [];
    const fields = headerCells.map((c) =>
      matchHeaderField(c.innerText || c.textContent || '')
    );
    if (!fields.some(Boolean)) return [];
    let switchColIndex = fields.indexOf('planStatus');
    if (switchColIndex < 0) switchColIndex = null;
    const dataRows = [
      ...root.querySelectorAll(
        '[role="row"], .ant-table-tbody tr, tbody tr'
      )
    ].filter((r) => r.querySelectorAll('[role="cell"], td').length && !r.querySelector('[role="columnheader"]'));

    const results = [];
    for (const tr of dataRows) {
      const cells = [...tr.querySelectorAll('[role="cell"], td')];
      if (!cells.length) continue;
      const row = {};
      fields.forEach((field, i) => {
        if (!field || !cells[i]) return;
        if (field === 'planStatus') {
          row.planStatus = parseSwitchFromEl(cells[i]) || 'unknown';
          return;
        }
        row[field] = cleanText(cells[i].innerText || cells[i].textContent || '');
      });
      if (!row.planStatus) {
        row.planStatus = detectPlanStatusFromRow(tr, cells, switchColIndex);
      }
      if (Object.keys(row).length) results.push(row);
    }
    return results;
  }

  function scoreRows(rows) {
    if (!rows?.length) return 0;
    let score = rows.length;
    for (const r of rows.slice(0, 5)) {
      if (r.campaign) score += 2;
      if (r.spend != null && r.spend !== '') score += 2;
      if (r.roi != null && r.roi !== '') score += 2;
      if (r.revenue != null && r.revenue !== '') score += 2;
      if (r.orders != null && r.orders !== '') score += 1;
    }
    return score;
  }

  function scrapeTablesFromDocument(doc) {
    const candidates = [];
    for (const table of doc.querySelectorAll('table')) {
      const rows = parseHtmlTable(table);
      const score = scoreRows(rows);
      if (score > 0) candidates.push({ rows, score, source: 'html-table' });
    }
    for (const el of doc.querySelectorAll(
      '.ant-table, [class*="Table"], [role="table"], [class*="campaign"]'
    )) {
      const rows = parseRoleTable(el);
      const score = scoreRows(rows);
      if (score > 0) candidates.push({ rows, score, source: 'role-table' });
    }
    candidates.sort((a, b) => b.score - a.score);
    if (!candidates.length) return { rows: [], source: 'none' };
    return { rows: candidates[0].rows, source: candidates[0].source };
  }

  function detectStoreName(doc) {
    // 1) 广告面板「xxx 主要账号」
    const allTextEls = [...doc.querySelectorAll('div, span, h1, h2, h3, a, p')].slice(0, 400);
    for (const el of allTextEls) {
      const t = cleanText(el.innerText || '');
      if (!t || t.length > 120) continue;
      if (/主要账号|主账号|main account/i.test(t)) {
        const name = t
          .replace(/主要账号|主账号|main account/gi, '')
          .replace(/\s+/g, ' ')
          .trim();
        if (name.length >= 2 && name.length < 80) return name;
        const parent = cleanText(el.parentElement?.innerText || '');
        const m = parent.match(/([^\n]{2,80}?)\s*(主要账号|主账号)/);
        if (m) return cleanText(m[1]);
      }
    }

    // 2) 常见店铺名节点
    for (const el of doc.querySelectorAll(
      '[class*="shop-name"], [class*="store-name"], [class*="seller-name"], [class*="account-name"], [data-e2e*="shop"]'
    )) {
      const t = cleanText(el.innerText || '');
      if (t && t.length >= 2 && t.length < 80 && !/tiktok|seller center/i.test(t)) return t;
    }

    // 3) title 拆分
    const title = cleanText(doc.title || '');
    const parts = title.split(/[-|–—]/).map(cleanText).filter(Boolean);
    const skip = /tiktok|seller|ads|shop ads|campaign|dashboard|homepage|商家中心|广告/i;
    for (const p of parts) {
      if (!skip.test(p) && p.length > 1 && p.length < 80) return p;
    }

    // 4) 标签页 / 顶栏残留（紫鸟窗口名有时带店名）
    try {
      const bar = cleanText(doc.querySelector('title')?.textContent || '');
      if (bar && !skip.test(bar) && bar.length < 80) return bar;
    } catch (_) {
      /* ignore */
    }
    return '';
  }

  // —— API parse ——
  function flattenObject(obj, prefix = '', out = {}, depth = 0) {
    if (!obj || typeof obj !== 'object' || depth > 4) return out;
    for (const [k, v] of Object.entries(obj)) {
      const key = prefix ? `${prefix}.${k}` : k;
      if (v && typeof v === 'object' && !Array.isArray(v)) {
        if (v.value != null) out[k] = v.value;
        flattenObject(v, key, out, depth + 1);
      } else if (!Array.isArray(v)) {
        out[k] = v;
        out[key] = v;
      }
    }
    return out;
  }

  function normalizeApiPlanStatus(v) {
    if (v == null || v === '') return null;
    if (typeof v === 'boolean') return v ? 'on' : 'off';
    if (typeof v === 'number') {
      if (v === 1) return 'on';
      if (v === 0) return 'off';
    }
    const s = String(v).trim().toLowerCase();
    if (/^(on|1|true|enable|enabled|open|active|running)$/i.test(s)) return 'on';
    if (/^(off|0|false|disable|disabled|close|closed|paused|inactive)$/i.test(s)) return 'off';
    return null;
  }

  function extractRow(obj) {
    const flat = flattenObject(obj);
    const row = {};
    for (const [field, keys] of Object.entries(KEY_MAP)) {
      for (const k of keys) {
        if (flat[k] != null && flat[k] !== '') {
          if (field === 'campaign') row[field] = cleanText(flat[k]);
          else if (field === 'planStatus') {
            row[field] = normalizeApiPlanStatus(flat[k]) || flat[k];
          } else row[field] = parseNumber(flat[k]) ?? flat[k];
          break;
        }
      }
      if (row[field] == null) {
        const lowerKeys = Object.keys(flat);
        for (const k of keys) {
          const hit = lowerKeys.find((x) => x.toLowerCase() === k.toLowerCase());
          if (hit && flat[hit] != null && flat[hit] !== '') {
            if (field === 'campaign') row[field] = cleanText(flat[hit]);
            else if (field === 'planStatus') {
              row[field] = normalizeApiPlanStatus(flat[hit]) || flat[hit];
            } else row[field] = parseNumber(flat[hit]) ?? flat[hit];
            break;
          }
        }
      }
    }
    return row;
  }

  function looksLikeReportRows(objs) {
    let hits = 0;
    for (const o of objs.slice(0, 5)) {
      const keys = Object.keys(o).join(' ').toLowerCase();
      if (/campaign|spend|cost|roi|roas|gmv|revenue|order|name/.test(keys)) hits += 1;
      if (o.metrics || o.stats || o.stat) hits += 1;
    }
    return hits >= 1;
  }

  function findArrayOfObjects(data, depth = 0) {
    if (depth > 8 || data == null) return [];
    if (Array.isArray(data)) {
      const objs = data.filter((x) => x && typeof x === 'object' && !Array.isArray(x));
      if (objs.length >= 1 && looksLikeReportRows(objs)) return objs;
      for (const item of data.slice(0, 20)) {
        const found = findArrayOfObjects(item, depth + 1);
        if (found.length) return found;
      }
      return objs.length >= 1 ? objs : [];
    }
    if (typeof data === 'object') {
      const prefer = ['list', 'rows', 'data', 'items', 'records', 'campaigns', 'result', 'table'];
      for (const k of prefer) {
        if (data[k] != null) {
          const found = findArrayOfObjects(data[k], depth + 1);
          if (found.length) return found;
        }
      }
      for (const v of Object.values(data)) {
        const found = findArrayOfObjects(v, depth + 1);
        if (found.length) return found;
      }
    }
    return [];
  }

  function parseApiPayload(payload) {
    let data = payload;
    if (typeof payload === 'string') {
      try {
        data = JSON.parse(payload);
      } catch {
        return [];
      }
    }
    const list = findArrayOfObjects(data);
    const rows = [];
    for (const item of list) {
      const row = extractRow(item);
      if (row.campaign || row.spend != null || row.revenue != null) rows.push(row);
    }
    return rows;
  }

  function injectHook() {
    try {
      const s = document.createElement('script');
      s.src = chrome.runtime.getURL('content/inject-fetch-hook.js');
      s.onload = () => s.remove();
      (document.documentElement || document.head).appendChild(s);
    } catch (e) {
      console.warn('[TK-Ad] inject hook failed', e);
    }
  }

  window.addEventListener('message', (event) => {
    if (event.source !== window) return;
    const data = event.data;
    if (!data || data.source !== 'tk-ad-scraper-hook' || data.type !== 'API_PAYLOAD') return;
    apiCache.unshift({ url: data.url, body: data.body, at: Date.now() });
    if (apiCache.length > API_CACHE_MAX) apiCache.length = API_CACHE_MAX;
  });

  function waitForTable(timeoutMs = 8000) {
    return new Promise((resolve) => {
      const start = Date.now();
      const tick = () => {
        const { rows, source } = scrapeTablesFromDocument(document);
        if (rows.length || Date.now() - start > timeoutMs) {
          resolve({ rows, source });
          return;
        }
        setTimeout(tick, 400);
      };
      tick();
    });
  }

  async function scrapePage(options = {}) {
    const waitMs = options.waitMs ?? 8000;
    let { rows, source } = await waitForTable(waitMs);

    // API 兜底 / 补充
    let apiRows = [];
    for (const item of apiCache) {
      const parsed = parseApiPayload(item.body);
      if (parsed.length > apiRows.length) {
        apiRows = parsed;
        source = source === 'none' ? 'api' : `${source}+api`;
      }
    }

    // 若 DOM 很弱而 API 更强，用 API
    if (scoreRows(apiRows) > scoreRows(rows)) {
      rows = apiRows;
      source = 'api';
    } else if (!rows.length && apiRows.length) {
      rows = apiRows;
      source = 'api';
    }

    const storeName = detectStoreName(document);
    const loginHint =
      /login|sign in|登录/i.test(document.body?.innerText?.slice(0, 500) || '') &&
      !rows.length;

    // 金额单位：与广告后台一致默认美金；从单元格文本识别 $ / £ 等
    const currencyHits = { USD: 0, GBP: 0, EUR: 0, CNY: 0 };
    for (const r of rows.slice(0, 30)) {
      for (const key of ['spend', 'revenue']) {
        const cur = detectCurrency(r[key]);
        if (cur && currencyHits[cur] != null) currencyHits[cur] += 1;
      }
    }
    let pageCurrency = 'USD';
    let maxHit = 0;
    for (const k of Object.keys(currencyHits)) {
      if (currencyHits[k] > maxHit) {
        maxHit = currencyHits[k];
        pageCurrency = k;
      }
    }

    return {
      ok: rows.length > 0,
      error: rows.length
        ? null
        : loginHint
          ? '页面可能未登录或未打开广告数据列表'
          : '未识别到广告数据表格，请打开广告系列/报表列表页后重试',
      rawRows: rows,
      source,
      currency: pageCurrency,
      storeName,
      pageTitle: document.title,
      url: location.href,
      apiCacheSize: apiCache.length,
      scrapedAt: new Date().toISOString()
    };
  }

  chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
    if (!msg || !msg.type) return;

    if (msg.type === 'PING') {
      sendResponse({ ok: true, url: location.href });
      return;
    }

    if (msg.type === 'SCRAPE_PAGE') {
      scrapePage(msg.options || {})
        .then((result) => sendResponse(result))
        .catch((e) =>
          sendResponse({
            ok: false,
            error: String(e.message || e),
            rawRows: [],
            url: location.href
          })
        );
      return true; // async
    }
  });

  injectHook();
  console.log('[TK-Ad] content script ready', location.href);
})();

extension\\scraper\\normalize.js.content:
/**
 * 字段归一化：统一为业务 5 字段 + 元数据
 */

/**
 * 从单元格文本识别币种（$ / £ / € 等）
 * @param {unknown} text
 * @returns {'USD'|'GBP'|'EUR'|'CNY'|null}
 */
export function detectCurrency(text) {
  const s = String(text ?? '');
  if (/[£]|GBP|英镑/i.test(s)) return 'GBP';
  if (/[€]|EUR|欧元/i.test(s)) return 'EUR';
  if (/[¥￥]|CNY|RMB|元/i.test(s) && !/\$/.test(s)) return 'CNY';
  if (/\$|USD|美金|美元/i.test(s)) return 'USD';
  return null;
}

/**
 * 从字符串解析数字（去掉货币符号、千分位、百分号）
 * 金额按美金口径使用；符号仅用于识别币种，不改变数值本身。
 * @param {unknown} value
 * @returns {number|null}
 */
export function parseNumber(value) {
  if (value == null || value === '') return null;
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  let s = String(value).trim();
  if (!s || s === '-' || s === '—') return null;
  s = s
    .replace(/[,\s]/g, '')
    .replace(/[¥$€£￥]/g, '')
    .replace(/USD|GBP|EUR|CNY|RMB|美金|美元|英镑|欧元/gi, '')
    .replace(/%/g, '');
  // 括号负数 (1.2) → -1.2
  const paren = s.match(/^\((.+)\)$/);
  if (paren) s = `-${paren[1]}`;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

/**
 * @param {string} text
 * @returns {string}
 */
export function cleanText(text) {
  return String(text ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * 解析业务日期 YYYY-MM-DD
 * @param {'yesterday'|'today'|'custom'} mode
 * @param {string} [customDate]
 */
export function resolveBizDate(mode, customDate) {
  if (mode === 'custom' && customDate) {
    return customDate.slice(0, 10);
  }
  const d = new Date();
  if (mode === 'yesterday') {
    d.setDate(d.getDate() - 1);
  }
  return formatDateLocal(d);
}

export function formatDateLocal(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

/**
 * 应用店铺名映射
 * @param {string} detected
 * @param {{alias:string,name:string}[]} mappings
 * @param {string} [fallback]
 */
export function mapStoreName(detected, mappings = [], fallback = '') {
  const raw = cleanText(detected || '');
  if (!raw && fallback) return fallback;
  for (const m of mappings) {
    if (!m?.alias) continue;
    if (raw.toLowerCase().includes(String(m.alias).toLowerCase()) ||
        String(m.alias).toLowerCase().includes(raw.toLowerCase())) {
      return m.name || m.alias;
    }
  }
  return raw || fallback || '未知店铺';
}

/**
 * 将原始行归一化为标准记录
 * @param {object} row
 * @param {object} ctx
 */
/**
 * 计划开关归一：on | off | unknown
 * @param {unknown} raw
 * @returns {'on'|'off'|'unknown'}
 */
export function normalizePlanStatus(raw) {
  if (raw == null || raw === '') return 'unknown';
  const s = String(raw).trim().toLowerCase();
  if (/^(on|1|true|open|enable|enabled|active|running|投放中|开启|开)$/i.test(s)) {
    return 'on';
  }
  if (
    /^(off|0|false|close|closed|disable|disabled|paused|inactive|已关闭|关闭|关|暂停)$/i.test(
      s
    )
  ) {
    return 'off';
  }
  return 'unknown';
}

export function normalizeRow(row, ctx = {}) {
  const campaign = cleanText(row.campaign ?? row.name ?? '');
  const spend = parseNumber(row.spend ?? row.cost);
  const orders = parseNumber(row.orders ?? row.units ?? row.sales_count);
  const roi = parseNumber(row.roi ?? row.roas);
  const revenue = parseNumber(row.revenue ?? row.gmv ?? row.income);
  // 与广告后台一致：落库单位为美金 USD
  const currency = cleanText(row.currency || ctx.currency || 'USD').toUpperCase() || 'USD';
  const planStatus = normalizePlanStatus(row.planStatus ?? row.switch ?? row.enabled);

  const filled = [campaign, spend, orders, roi, revenue].filter(
    (v) => v !== null && v !== ''
  ).length;

  let status = 'success';
  if (!campaign && filled === 0) status = 'error';
  else if (filled < 4) status = 'partial';

  return {
    date: ctx.date || resolveBizDate('yesterday'),
    store: ctx.storeName || '未知店铺',
    storeId: ctx.storeId || '',
    campaign,
    spend: spend ?? 0,
    orders: orders ?? 0,
    roi: roi ?? 0,
    revenue: revenue ?? 0,
    currency,
    scrapedAt: ctx.scrapedAt || new Date().toISOString(),
    sourceUrl: ctx.sourceUrl || '',
    status,
    planStatus
  };
}

/**
 * 过滤空行 / 汇总行；策略 C：已关闭且花费=0且销售额=0 跳过
 * @param {ReturnType<typeof normalizeRow>[]} rows
 * @param {{ skipZeroDisabled?: boolean }} [opts]
 */
export function filterValidRows(rows, opts = {}) {
  const skipZeroDisabled = opts.skipZeroDisabled !== false;
  return rows.filter((r) => {
    if (!r) return false;
    if (!r.campaign) return false;
    const lower = r.campaign.toLowerCase();
    if (['total', '合计', '总计', '汇总', 'summary', 'all'].includes(lower)) {
      return false;
    }
    if (skipZeroDisabled) {
      const ps = normalizePlanStatus(r.planStatus);
      const spend = Number(r.spend) || 0;
      const revenue = Number(r.revenue) || 0;
      if (ps === 'off' && spend === 0 && revenue === 0) return false;
    }
    return true;
  });
}

scripts\\run-multi-store.ps1.content:
﻿# Multi-store TikTok ad scrape via ziniao-cli (dynamic store list)
# Usage:
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -DryRun true
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -DryRun false
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-multi-store.ps1 -ListOnly
#
# Requires: Ziniao client running + ziniao-cli doctor OK
# Config: config\stores.config.json

param(
  [string]$ConfigPath = "",
  [switch]$ListOnly,
  # string so -File callers work (Nullable[bool] cannot bind "$true"/"$false" from -File)
  # omit / empty => use config.options.dryRun; true|1|yes / false|0|no
  [string]$DryRun = ""
)

$ErrorActionPreference = 'Stop'
# ziniao-cli writes progress to stderr; do not treat as terminating
$PSNativeCommandUseErrorActionPreference = $false
$root = Split-Path $PSScriptRoot -Parent
if (-not $ConfigPath) {
  $ConfigPath = Join-Path $root 'config\stores.config.json'
}
$scrapeJsPath = Join-Path $root 'scripts\scrape-ads-page.js'

if (-not (Test-Path $ConfigPath)) {
  throw "Missing config: $ConfigPath (copy config\stores.config.example.json)"
}
if (-not (Test-Path $scrapeJsPath)) {
  throw "Missing scrape script: $scrapeJsPath"
}

$cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
$scrapeJs = Get-Content $scrapeJsPath -Raw -Encoding UTF8
$analysisLib = Join-Path $PSScriptRoot 'daily-analysis.ps1'
if (Test-Path $analysisLib) { . $analysisLib }
$qingquanLib = Join-Path $PSScriptRoot 'qingquan-client.ps1'
if (Test-Path $qingquanLib) { . $qingquanLib }

function Write-Step([string]$msg) {
  Write-Host ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg)
}

function Get-BizDate([string]$mode) {
  $d = Get-Date
  if ($mode -eq 'yesterday') { $d = $d.AddDays(-1) }
  return $d.ToString('yyyy-MM-dd')
}

# 计划开关归一：on | off | unknown
function Normalize-PlanStatus($raw) {
  if ($null -eq $raw) { return 'unknown' }
  $s = ([string]$raw).Trim().ToLowerInvariant()
  if ([string]::IsNullOrWhiteSpace($s)) { return 'unknown' }
  if ($s -match '^(on|1|true|open|enable|enabled|active|running|投放中|开启|开)$') { return 'on' }
  if ($s -match '^(off|0|false|close|closed|disable|disabled|paused|inactive|已关闭|关闭|关|暂停)$') { return 'off' }
  return 'unknown'
}

# 策略 C：已关闭 且 花费=0 且 销售额=0 → 跳过；有花费/销售额的关闭计划仍保留
function Test-SkipZeroDisabledCampaign($row) {
  $ps = Normalize-PlanStatus $row.planStatus
  if ($ps -ne 'off') { return $false }
  $spend = 0.0
  if ($null -ne $row.spend) { $spend = [double]$row.spend }
  $revenue = 0.0
  if ($null -ne $row.revenue) { $revenue = [double]$row.revenue }
  return ($spend -eq 0 -and $revenue -eq 0)
}

function Test-StoreFilter($store, $filter) {
  if ($filter.includeStoreIds -and @($filter.includeStoreIds).Count -gt 0) {
    if ($store.storeId -notin @($filter.includeStoreIds)) { return $false }
  }
  if ($filter.excludeStoreIds -and ($store.storeId -in @($filter.excludeStoreIds))) {
    return $false
  }
  if ($filter.requireIp -eq $true) {
    if (-not $store.ip -or [string]::IsNullOrWhiteSpace([string]$store.ip)) { return $false }
  }
  $platform = [string]$store.platformName
  $name = [string]$store.storeName
  if ($filter.platformContains -and @($filter.platformContains).Count -gt 0) {
    $ok = $false
    foreach ($p in @($filter.platformContains)) {
      if ($platform -like "*$p*") { $ok = $true; break }
    }
    if (-not $ok) { return $false }
  }
  if ($filter.nameContains -and @($filter.nameContains).Count -gt 0) {
    $ok = $false
    foreach ($p in @($filter.nameContains)) {
      if ($name -like "*$p*") { $ok = $true; break }
    }
    if (-not $ok) { return $false }
  }
  if ($filter.nameExclude) {
    foreach ($p in @($filter.nameExclude)) {
      if ($name -like "*$p*") { return $false }
    }
  }
  return $true
}

function Get-AdsUrl($store, $adsUrlCfg) {
  $platform = [string]$store.platformName
  if ($adsUrlCfg.byPlatform) {
    foreach ($p in $adsUrlCfg.byPlatform.PSObject.Properties) {
      if ($p.Name -eq $platform) { return [string]$p.Value }
    }
    foreach ($p in $adsUrlCfg.byPlatform.PSObject.Properties) {
      if ($platform -like "*$($p.Name)*") { return [string]$p.Value }
    }
  }
  return [string]$adsUrlCfg.default
}

function Get-DisplayName($store, $map) {
  $name = [string]$store.storeName
  if ($map) {
    foreach ($p in $map.PSObject.Properties) {
      if ($p.Name -eq $name) { return [string]$p.Value }
    }
    foreach ($p in $map.PSObject.Properties) {
      if ($name -like "*$($p.Name)*" -or $p.Name -like "*$name*") {
        return [string]$p.Value
      }
    }
  }
  return $name
}

function Maximize-ZiniaoBrowserWindows {
  # 紫鸟开店默认常是小窗；Win32 最大化有助于广告表完整渲染
  $code = @'
using System;
using System.Text;
using System.Collections.Generic;
using System.Runtime.InteropServices;

public class ZiniaoWinMax {
  public delegate bool EnumProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder lpClassName, int nMaxCount);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
  const int SW_MAXIMIZE = 3;

  public static int MaximizeMatching() {
    int n = 0;
    EnumWindows((hWnd, l) => {
      if (!IsWindowVisible(hWnd)) return true;
      var title = new StringBuilder(512);
      var cls = new StringBuilder(256);
      GetWindowText(hWnd, title, title.Capacity);
      GetClassName(hWnd, cls, cls.Capacity);
      string t = title.ToString();
      string c = cls.ToString();
      // 紫鸟店铺窗多为 Chromium；标题常含 TikTok / seller / 店铺名
      bool chrome = c.IndexOf("Chrome_WidgetWin", StringComparison.OrdinalIgnoreCase) >= 0
                 || c.IndexOf("Chrome_WidgetWin_1", StringComparison.OrdinalIgnoreCase) >= 0;
      bool hint = t.IndexOf("TikTok", StringComparison.OrdinalIgnoreCase) >= 0
               || t.IndexOf("tiktok", StringComparison.OrdinalIgnoreCase) >= 0
               || t.IndexOf("seller", StringComparison.OrdinalIgnoreCase) >= 0
               || t.IndexOf("紫鸟", StringComparison.OrdinalIgnoreCase) >= 0
               || t.IndexOf("Ziniao", StringComparison.OrdinalIgnoreCase) >= 0
               || t.IndexOf("ads-creation", StringComparison.OrdinalIgnoreCase) >= 0;
      if (chrome && (hint || t.Length > 0)) {
        // 避免把用户普通 Chrome 主页误最大化：要求标题像店铺/广告或非空且 chrome
        if (hint || t.IndexOf("Shop", StringComparison.OrdinalIgnoreCase) >= 0) {
          ShowWindow(hWnd, SW_MAXIMIZE);
          n++;
        }
      }
      return true;
    }, IntPtr.Zero);
    return n;
  }
}
'@
  if (-not ('ZiniaoWinMax' -as [type])) {
    Add-Type -TypeDefinition $code -ErrorAction Stop
  }
  return [ZiniaoWinMax]::MaximizeMatching()
}

function Get-CurrencyConfig($cfg) {
  # 与 TikTok 广告后台一致：广告花费 / 销售额统一按美金(USD) 落库与写飞书
  $target = 'USD'
  $pageDefault = 'USD'
  $convert = $true
  $rates = @{
    USD = 1.0
    GBP = 1.27
    EUR = 1.08
    CNY = 0.14
  }
  if ($cfg.currency) {
    if ($cfg.currency.target) { $target = ([string]$cfg.currency.target).ToUpperInvariant() }
    if ($cfg.currency.pageDefault) { $pageDefault = ([string]$cfg.currency.pageDefault).ToUpperInvariant() }
    if ($null -ne $cfg.currency.convert) { $convert = [bool]$cfg.currency.convert }
    if ($cfg.currency.ratesToUsd) {
      foreach ($p in $cfg.currency.ratesToUsd.PSObject.Properties) {
        try { $rates[$p.Name.ToUpperInvariant()] = [double]$p.Value } catch { }
      }
    }
  }
  return [pscustomobject]@{
    target      = $target
    pageDefault = $pageDefault
    convert     = $convert
    ratesToUsd  = $rates
  }
}

function Convert-MoneyToTarget {
  param(
    [double]$Amount,
    [string]$FromCurrency,
    [string]$TargetCurrency,
    $RatesToUsd
  )
  $from = if ($FromCurrency) { $FromCurrency.ToUpperInvariant() } else { 'USD' }
  $to = if ($TargetCurrency) { $TargetCurrency.ToUpperInvariant() } else { 'USD' }
  if ($from -eq $to) { return [math]::Round($Amount, 2) }
  $rateFrom = 1.0
  $rateTo = 1.0
  if ($RatesToUsd.ContainsKey($from)) { $rateFrom = [double]$RatesToUsd[$from] }
  if ($RatesToUsd.ContainsKey($to)) { $rateTo = [double]$RatesToUsd[$to] }
  if ($rateFrom -le 0 -or $rateTo -le 0) { return [math]::Round($Amount, 2) }
  # ratesToUsd: 1 unit of currency → USD；先转 USD 再转目标币
  $usd = $Amount * $rateFrom
  return [math]::Round($usd / $rateTo, 2)
}

function Get-FeishuToken($appId, $appSecret) {
  $body = @{ app_id = $appId; app_secret = $appSecret } | ConvertTo-Json
  $r = Invoke-RestMethod -Method POST -Uri 'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal' `
    -ContentType 'application/json; charset=utf-8' -Body $body
  if ($r.code -ne 0) { throw "Feishu token failed: $($r.msg)" }
  return $r.tenant_access_token
}

function Write-FeishuRows($feishu, $rows, $dryRun) {
  if ($dryRun) {
    Write-Step ("  [dry-run] skip Feishu write, rows={0}" -f $rows.Count)
    return @{ written = 0; dryRun = $true }
  }
  if (-not $rows.Count) { return @{ written = 0; dryRun = $false } }

  $token = Get-FeishuToken $feishu.appId $feishu.appSecret
  $url = "https://open.feishu.cn/open-apis/bitable/v1/apps/$($feishu.appToken)/tables/$($feishu.tableId)/records/batch_create"
  $fieldsUrl = "https://open.feishu.cn/open-apis/bitable/v1/apps/$($feishu.appToken)/tables/$($feishu.tableId)/fields?page_size=100"
  $fieldList = Invoke-RestMethod -Method GET -Uri $fieldsUrl -Headers @{ Authorization = "Bearer $token" }
  $names = @($fieldList.data.items | ForEach-Object { $_.field_name })

  function Pick-Name([string[]]$aliases) {
    foreach ($a in $aliases) { if ($names -contains $a) { return $a } }
    return $null
  }

  # UTF-8 field names (same as extension BITABLE_FIELDS)
  $utf8 = [System.Text.Encoding]::UTF8
  $A_DATE = @($utf8.GetString([byte[]](0xE6,0x97,0xA5,0xE6,0x9C,0x9F)))
  $A_STORE = @($utf8.GetString([byte[]](0xE5,0xBA,0x97,0xE9,0x93,0xBA)))
  $A_STORE_ID = @($utf8.GetString([byte[]](0xE5,0xBA,0x97,0xE9,0x93,0xBA,0x49,0x44)))
  $A_CAMPAIGN = @(
    $utf8.GetString([byte[]](0xE5,0x93,0x81,0xE5,0x90,0x8D)),
    $utf8.GetString([byte[]](0xE5,0xB9,0xBF,0xE5,0x91,0x8A,0xE7,0xB3,0xBB,0xE5,0x88,0x97,0xE5,0x90,0x8D,0xE7,0xA7,0xB0))
  )
  $A_SPEND = @(
    $utf8.GetString([byte[]](0xE5,0xB9,0xBF,0xE5,0x91,0x8A,0xE8,0x8A,0xB1,0xE8,0xB4,0xB9)),
    $utf8.GetString([byte[]](0xE6,0x88,0x90,0xE6,0x9C,0xAC))
  )
  $A_ORDERS = @($utf8.GetString([byte[]](0xE9,0x94,0x80,0xE9,0x87,0x8F)))
  $A_ROI = @('ROI')
  $A_REVENUE = @(
    $utf8.GetString([byte[]](0xE9,0x94,0x80,0xE5,0x94,0xAE,0xE9,0xA2,0x9D)),
    $utf8.GetString([byte[]](0xE6,0x80,0xBB,0xE6,0x94,0xB6,0xE5,0x85,0xA5))
  )
  $A_SCRAPED = @($utf8.GetString([byte[]](0xE6,0x8A,0x93,0xE5,0x8F,0x96,0xE6,0x97,0xB6,0xE9,0x97,0xB4)))
  $A_URL = @($utf8.GetString([byte[]](0xE6,0x95,0xB0,0xE6,0x8D,0xAE,0xE6,0xBA,0x90,0x55,0x52,0x4C)))
  $A_STATUS = @($utf8.GetString([byte[]](0xE7,0x8A,0xB6,0xE6,0x80,0x81)))
  # 计划状态 / 投放状态 / 开关
  $A_PLAN = @(
    $utf8.GetString([byte[]](0xE8,0xAE,0xA1,0xE5,0x88,0x92,0xE7,0x8A,0xB6,0xE6,0x80,0x81)),
    $utf8.GetString([byte[]](0xE6,0x8A,0x95,0xE6,0x94,0xBE,0xE7,0x8A,0xB6,0xE6,0x80,0x81)),
    $utf8.GetString([byte[]](0xE5,0xBC,0x80,0xE5,0x85,0xB3))
  )

  $fn = @{
    date       = Pick-Name $A_DATE
    store      = Pick-Name $A_STORE
    storeId    = Pick-Name $A_STORE_ID
    campaign   = Pick-Name $A_CAMPAIGN
    spend      = Pick-Name $A_SPEND
    orders     = Pick-Name $A_ORDERS
    roi        = Pick-Name $A_ROI
    revenue    = Pick-Name $A_REVENUE
    scrapedAt  = Pick-Name $A_SCRAPED
    sourceUrl  = Pick-Name $A_URL
    status     = Pick-Name $A_STATUS
    planStatus = Pick-Name $A_PLAN
  }

  if (-not $fn.campaign -or -not $fn.store) {
    throw ("Feishu fields incomplete. Have: {0}" -f ($names -join ', '))
  }

  $records = @()
  foreach ($row in $rows) {
    $fields = @{}
    if ($fn.date) {
      $dt = [DateTime]::ParseExact($row.date, 'yyyy-MM-dd', $null)
      $fields[$fn.date] = [DateTimeOffset]::new($dt).ToUnixTimeMilliseconds()
    }
    if ($fn.store) { $fields[$fn.store] = $row.store }
    if ($fn.storeId) { $fields[$fn.storeId] = $row.storeId }
    if ($fn.campaign) { $fields[$fn.campaign] = $row.campaign }
    if ($fn.spend) { $fields[$fn.spend] = [double]$row.spend }
    if ($fn.orders) { $fields[$fn.orders] = [double]$row.orders }
    if ($fn.roi) { $fields[$fn.roi] = [double]$row.roi }
    if ($fn.revenue) { $fields[$fn.revenue] = [double]$row.revenue }
    if ($fn.scrapedAt) { $fields[$fn.scrapedAt] = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds() }
    if ($fn.sourceUrl) { $fields[$fn.sourceUrl] = $row.sourceUrl }
    if ($fn.status) { $fields[$fn.status] = $row.status }
    if ($fn.planStatus -and $row.planStatus) {
      $ps = [string]$row.planStatus
      # 飞书展示：on/off/unknown → 投放中/已关闭/未知
      if ($ps -eq 'on') { $ps = $utf8.GetString([byte[]](0xE6,0x8A,0x95,0xE6,0x94,0xBE,0xE4,0xB8,0xAD)) }
      elseif ($ps -eq 'off') { $ps = $utf8.GetString([byte[]](0xE5,0xB7,0xB2,0xE5,0x85,0xB3,0xE9,0x97,0xAD)) }
      elseif ($ps -eq 'unknown') { $ps = $utf8.GetString([byte[]](0xE6,0x9C,0xAA,0xE7,0x9F,0xA5)) }
      $fields[$fn.planStatus] = $ps
    }
    $records += @{ fields = $fields }
  }

  $bodyBytes = [System.Text.Encoding]::UTF8.GetBytes((@{ records = $records } | ConvertTo-Json -Depth 8 -Compress))
  $resp = Invoke-RestMethod -Method POST -Uri $url -Headers @{ Authorization = "Bearer $token" } `
    -ContentType 'application/json; charset=utf-8' -Body $bodyBytes
  if ($resp.code -ne 0) {
    throw ("Feishu write failed: code={0} msg={1}" -f $resp.code, $resp.msg)
  }
  return @{ written = $records.Count; dryRun = $false }
}

# --- main ---
function ConvertTo-ProcessArgument([string]$arg) {
  # CommandLineToArgvW-style quoting for ProcessStartInfo.Arguments
  if ($null -eq $arg) { return '""' }
  if ($arg -notmatch '[\s"]') { return $arg }
  $bs = [char]0x5C
  $sb = New-Object System.Text.StringBuilder
  [void]$sb.Append([char]0x22)
  $backslashes = 0
  foreach ($ch in $arg.ToCharArray()) {
    if ($ch -eq $bs) {
      $backslashes++
      continue
    }
    if ($ch -eq [char]0x22) {
      [void]$sb.Append($bs, $backslashes * 2 + 1)
      [void]$sb.Append([char]0x22)
      $backslashes = 0
      continue
    }
    if ($backslashes -gt 0) {
      [void]$sb.Append($bs, $backslashes)
      $backslashes = 0
    }
    [void]$sb.Append($ch)
  }
  if ($backslashes -gt 0) { [void]$sb.Append($bs, $backslashes * 2) }
  [void]$sb.Append([char]0x22)
  return $sb.ToString()
}

# Cache: npm ziniao-cli is a .ps1 shim — Process.Start cannot run it; invoke node + run.js directly
$script:ZiniaoNode = $null
$script:ZiniaoRunJs = $null

function Initialize-ZiniaoCli {
  if ($script:ZiniaoNode -and $script:ZiniaoRunJs) { return }

  $nodeCmd = Get-Command node -ErrorAction SilentlyContinue
  if (-not $nodeCmd) { throw "node not found in PATH (required by ziniao-cli)" }
  $script:ZiniaoNode = $nodeCmd.Source

  $candidates = @()
  $npmDir = Join-Path $env:APPDATA 'npm'
  if ($npmDir) {
    $candidates += (Join-Path $npmDir 'node_modules\@ziniao-open\cli\scripts\run.js')
  }
  $cmd = Get-Command ziniao-cli -ErrorAction SilentlyContinue
  if ($cmd -and $cmd.Source) {
    $base = Split-Path $cmd.Source -Parent
    $candidates += (Join-Path $base 'node_modules\@ziniao-open\cli\scripts\run.js')
  }
  foreach ($c in $candidates) {
    if ($c -and (Test-Path -LiteralPath $c)) {
      $script:ZiniaoRunJs = (Resolve-Path -LiteralPath $c).Path
      break
    }
  }
  if (-not $script:ZiniaoRunJs) {
    throw "ziniao-cli run.js not found. Install: npm i -g @ziniao-open/cli  (looked under %APPDATA%\npm\node_modules\@ziniao-open\cli)"
  }
  Write-Step ("ziniao runtime: node={0} run.js={1}" -f $script:ZiniaoNode, $script:ZiniaoRunJs)
}

function Invoke-Ziniao([string[]]$CliArgs) {
  # UTF-8 capture via ProcessStartInfo. npm ziniao-cli is .ps1 — call node run.js instead.
  Initialize-ZiniaoCli
  $utf8 = [System.Text.UTF8Encoding]::new($false)

  $allArgs = @($script:ZiniaoRunJs) + @($CliArgs)
  $argLine = ($allArgs | ForEach-Object { ConvertTo-ProcessArgument ([string]$_) }) -join ' '

  $psi = New-Object System.Diagnostics.ProcessStartInfo
  $psi.FileName = $script:ZiniaoNode
  $psi.Arguments = $argLine
  $psi.UseShellExecute = $false
  $psi.RedirectStandardOutput = $true
  $psi.RedirectStandardError = $true
  $psi.CreateNoWindow = $true
  $psi.StandardOutputEncoding = $utf8
  $psi.StandardErrorEncoding = $utf8

  $p = New-Object System.Diagnostics.Process
  $p.StartInfo = $psi
  try {
    [void]$p.Start()
  } catch {
    throw "Failed to start ziniao (node): $($_.Exception.Message)"
  }
  $stdout = $p.StandardOutput.ReadToEnd()
  $stderr = $p.StandardError.ReadToEnd()
  $p.WaitForExit()

  $parts = @()
  if (-not [string]::IsNullOrEmpty($stdout)) { $parts += $stdout.TrimEnd("`r", "`n") }
  if (-not [string]::IsNullOrEmpty($stderr)) { $parts += $stderr.TrimEnd("`r", "`n") }
  return ($parts -join "`n")
}

function Save-ScrapeDebug {
  param(
    [string]$StoreId,
    [string]$StoreName,
    [string]$DisplayName,
    [string]$AdsUrl,
    [string]$ExecOut,
    $Payload,
    [string]$ErrorMsg,
    [switch]$AsLast
  )
  $logsDir = Join-Path $root 'logs'
  New-Item -ItemType Directory -Force -Path $logsDir | Out-Null
  $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
  $path = if ($AsLast) {
    Join-Path $logsDir 'scrape-debug-last.json'
  } else {
    Join-Path $logsDir ("scrape-debug-{0}-{1}.json" -f $StoreId, $stamp)
  }
  $previewLen = 8000
  $execPreview = $ExecOut
  if ($execPreview -and $execPreview.Length -gt $previewLen) {
    $execPreview = $execPreview.Substring(0, $previewLen) + '...[truncated]'
  }
  $obj = [ordered]@{
    storeId       = $StoreId
    storeName     = $StoreName
    displayName   = $DisplayName
    adsUrl        = $AdsUrl
    error         = $ErrorMsg
    execOutLength = if ($ExecOut) { $ExecOut.Length } else { 0 }
    execOut       = $execPreview
    payload       = $Payload
    payloadUrl    = if ($Payload -and $Payload.url) { [string]$Payload.url } else { $null }
    capturedAt    = (Get-Date).ToString('o')
  }
  ($obj | ConvertTo-Json -Depth 10) | Set-Content -Path $path -Encoding UTF8
  Write-Step ("  debug saved: {0}" -f $path)
  return $path
}

function ConvertTo-ScrapeOneLine([string]$js) {
  # // comments become catastrophic when newlines are removed — strip first
  $s = [regex]::Replace($js, '/\*[\s\S]*?\*/', ' ')
  $s = [regex]::Replace($s, '(?m)^\s*//.*$', '')
  $s = [regex]::Replace($s, '(?m)([^:"''\\])//[^\r\n]*', '$1')
  $s = ($s -replace '\r?\n', ' ' -replace '\s+', ' ').Trim()
  if ($s -notmatch '\)\s*\(\s*\)\s*;?\s*$' -and $s -notmatch '\}\s*\)\s*\(\s*\)\s*;?\s*$') {
    Write-Step "WARN scrape script may be truncated (len=$($s.Length))"
  }
  return $s
}

function ConvertFrom-JsonSafe([string]$text) {
  if ([string]::IsNullOrWhiteSpace($text)) { return $null }
  try { return ($text | ConvertFrom-Json) } catch { return $null }
}

function Get-ScrapePayload([string]$execOut) {
  # ziniao-cli page exec shapes seen in the wild:
  #   { ok, data: { ok, storeId, data: { exceptionDetails, result: "<json string>", targetId } } }
  #   { ok, data: { data: { result: { type, value: "<json string>" } } } }  (raw CDP)
  # Our scraper returns JSON.stringify({ ok, rows, source, url, error })
  function Test-ScrapeShape($o) {
    if ($null -eq $o) { return $false }
    if ($o -is [string]) { return $false }
    $names = @($o.PSObject.Properties.Name)
    return ($names -contains 'rows') -or (($names -contains 'ok') -and ($names -contains 'source' -or $names -contains 'error'))
  }
  function Convert-MaybeJsonString($v) {
    if ($v -is [string]) {
      $inner = ConvertFrom-JsonSafe $v
      if (Test-ScrapeShape $inner) { return $inner }
      return $null
    }
    if (Test-ScrapeShape $v) { return $v }
    if ($v -and ($v.PSObject.Properties.Name -contains 'value')) {
      return Convert-MaybeJsonString $v.value
    }
    return $null
  }

  $root = ConvertFrom-JsonSafe $execOut
  if (-not $root) {
    if ($execOut -match '(?s)(\{\s*"ok"\s*:\s*(?:true|false)\s*,\s*"source"[\s\S]*?"rows"\s*:\s*\[[\s\S]*?\})') {
      return (ConvertFrom-JsonSafe $Matches[1])
    }
    return $null
  }

  # Walk common nest paths first
  $paths = @(
    { param($r) $r },
    { param($r) $r.data },
    { param($r) $r.data.data },
    { param($r) $r.data.result },
    { param($r) $r.data.data.result },
    { param($r) $r.data.data.result.value },
    { param($r) $r.result },
    { param($r) $r.result.value }
  )
  foreach ($get in $paths) {
    try {
      $node = & $get $root
    } catch { continue }
    if ($null -eq $node) { continue }

    # exception on this node?
    if ($node -isnot [string] -and $node.PSObject.Properties.Name -contains 'exceptionDetails' -and $node.exceptionDetails) {
      $ex = $node.exceptionDetails
      $msg = if ($ex.exception -and $ex.exception.description) { [string]$ex.exception.description }
             elseif ($ex.text) { [string]$ex.text }
             else { 'page exec exception' }
      return [pscustomobject]@{ ok = $false; rows = @(); error = $msg; source = 'exception' }
    }

    $parsed = Convert-MaybeJsonString $node
    if ($parsed) { return $parsed }

    # node has .result string/object
    if ($node -isnot [string] -and $node.PSObject.Properties.Name -contains 'result') {
      $parsed = Convert-MaybeJsonString $node.result
      if ($parsed) { return $parsed }
    }
  }

  # Fallback: unescaped scrape JSON embedded in the CLI text
  if ($execOut -match '(?s)(\{\s*"ok"\s*:\s*(?:true|false)\s*,\s*"source"\s*:[\s\S]*?"rows"\s*:\s*\[[\s\S]*?\})') {
    $inner = ConvertFrom-JsonSafe $Matches[1]
    if ($inner) { return $inner }
  }
  # Escaped form inside result:"{...}"
  if ($execOut -match '"result"\s*:\s*"(\{\\"ok\\".+?\})"') {
    $unescaped = $Matches[1] -replace '\\"', '"' -replace '\\\\', '\'
    $inner = ConvertFrom-JsonSafe $unescaped
    if ($inner) { return $inner }
  }

  return [pscustomobject]@{
    ok         = $false
    rows       = @()
    error      = 'unrecognized page exec payload'
    source     = 'parse'
    rawPreview = if ($execOut.Length -gt 400) { $execOut.Substring(0, 400) } else { $execOut }
  }
}

Write-Step "check ziniao-cli..."
$doctorText = Invoke-Ziniao @('doctor')
if ($doctorText -notmatch 'ZClaw|Bridge|ok|OK|通过') {
  Write-Host $doctorText
  # soft warn only
}

Write-Step "list stores (dynamic)..."
$listRaw = Invoke-Ziniao @('store', 'list', '--format', 'json')
if ($listRaw -match '(?s)\{[\s\S]*"ok"\s*:\s*true[\s\S]*\}') {
  $listRaw = $Matches[0]
}
$listObj = $listRaw | ConvertFrom-Json
if (-not $listObj.ok) { throw "store list failed: $listRaw" }
$all = @($listObj.data.items)
Write-Step ("ziniao stores total: {0}" -f $all.Count)

$selected = @($all | Where-Object { Test-StoreFilter $_ $cfg.filter })
Write-Step ("after filter: {0}" -f $selected.Count)
foreach ($s in $selected) {
  $disp = Get-DisplayName $s $cfg.storeNameMap
  $ip = if ($s.ip) { $s.ip } else { '(no-ip)' }
  Write-Host ("  - {0} | {1} => Feishu[{2}] | {3} | {4}" -f $s.storeId, $s.storeName, $disp, $s.platformName, $ip)
}

if ($ListOnly) {
  Write-Step "ListOnly done."
  exit 0
}

if ($selected.Count -eq 0) {
  throw "No stores matched filter. Adjust requireIp / platformContains / excludeStoreIds."
}

function Convert-DryRunFlag([string]$raw) {
  if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
  switch -Regex ($raw.Trim()) {
    '^(?i:true|1|yes|y|\$true)$'  { return $true }
    '^(?i:false|0|no|n|\$false)$' { return $false }
    default { throw "Invalid -DryRun value '$raw' (use true/false, or omit to use config)" }
  }
}
$dryRunParsed = Convert-DryRunFlag $DryRun
$useDryRun = if ($null -ne $dryRunParsed) { [bool]$dryRunParsed } else { [bool]$cfg.options.dryRun }
$bizDate = Get-BizDate $cfg.options.dateMode
$currencyCfg = Get-CurrencyConfig $cfg
$scrapeRetries = 2
$scrapeRetryWaitMs = 12000
if ($null -ne $cfg.options.scrapeRetries) { $scrapeRetries = [int]$cfg.options.scrapeRetries }
if ($null -ne $cfg.options.scrapeRetryWaitMs) { $scrapeRetryWaitMs = [int]$cfg.options.scrapeRetryWaitMs }
if ($scrapeRetries -lt 1) { $scrapeRetries = 1 }
$skipZeroDisabled = $true
if ($null -ne $cfg.options -and $null -ne $cfg.options.skipZeroDisabledCampaigns) {
  $skipZeroDisabled = [bool]$cfg.options.skipZeroDisabledCampaigns
}
Write-Step ("bizDate={0} dryRun={1} scrapeRetries={2} waitAfterVisitMs={3}" -f $bizDate, $useDryRun, $scrapeRetries, $cfg.options.waitAfterVisitMs)
Write-Step ("currency target={0} pageDefault={1} convert={2} (广告花费/销售额统一按美金)" -f $currencyCfg.target, $currencyCfg.pageDefault, $currencyCfg.convert)
Write-Step ("skipZeroDisabledCampaigns={0} (C: skip off+spend0+revenue0 only)" -f $skipZeroDisabled)
if (-not $useDryRun) {
  Write-Step "NOTE: Feishu write is APPEND — same bizDate re-run will create duplicate rows. Clean Feishu if you re-ran today."
}

function Get-FriendlyScrapeError($payload, [string]$fallback) {
  $url = ''
  if ($payload -and $payload.url) { $url = [string]$payload.url }
  if ($url -match 'settle/verification|verification') {
    return "店铺被重定向到核验/结算页，无法进广告面板: $url （请在卖家中心完成核验后重试）"
  }
  if ($url -match 'login|passport|signin') {
    return "页面疑似未登录/掉登录: $url"
  }
  $base = if ($fallback) { $fallback } else { 'scrape failed' }
  if ($url) { return "$base | url=$url" }
  return $base
}

$summary = @()
$allCampaignRows = @()
$scrapeOneLine = ConvertTo-ScrapeOneLine $scrapeJs
Write-Step ("scrape script one-line length={0}" -f $scrapeOneLine.Length)

$analysisEnabled = $true
$lowRoi = 3.0
$writeSummaryFeishu = $true
if ($cfg.analysis) {
  if ($null -ne $cfg.analysis.enabled) { $analysisEnabled = [bool]$cfg.analysis.enabled }
  if ($null -ne $cfg.analysis.lowRoiThreshold) { $lowRoi = [double]$cfg.analysis.lowRoiThreshold }
  if ($null -ne $cfg.analysis.writeSummaryToFeishu) { $writeSummaryFeishu = [bool]$cfg.analysis.writeSummaryToFeishu }
}

foreach ($store in $selected) {
  $sid = $store.storeId
  $sname = $store.storeName
  $display = Get-DisplayName $store $cfg.storeNameMap
  $adsUrl = Get-AdsUrl $store $cfg.adsUrl
  $item = [ordered]@{
    storeId          = $sid
    storeName        = $sname
    displayName      = $display
    ok               = $false
    rows             = 0
    written          = 0
    qingquanAccepted = 0
    qingquanDup      = 0
    qingquanError    = $null
    error            = $null
  }

  Write-Step ("==== START {0} ({1}) => {2} ====" -f $sname, $sid, $display)
  $execOut = $null
  $payload = $null
  $debugSaved = $false
  try {
    Write-Step "  open store..."
    # 默认尽量拉大窗口：紫鸟 open 支持 --window-ratio；再配合 page 内 resize / Win32 最大化
    $openArgs = [System.Collections.Generic.List[string]]::new()
    $openArgs.AddRange([string[]]@('store', 'open', '--id', $sid, '--url', $adsUrl))
    $windowRatio = 'full'
    if ($cfg.options -and $cfg.options.windowRatio) {
      $windowRatio = [string]$cfg.options.windowRatio
    }
    if ($windowRatio -and $windowRatio -ne 'default' -and $windowRatio -ne 'none') {
      $openArgs.Add('--window-ratio')
      $openArgs.Add($windowRatio)
      Write-Step ("  open with --window-ratio {0}" -f $windowRatio)
    }
    Write-Host (Invoke-Ziniao @($openArgs.ToArray()))
    Start-Sleep -Milliseconds ([int]$cfg.options.waitAfterOpenMs)

    $doMaximize = $true
    if ($cfg.options -and $null -ne $cfg.options.maximizeWindow) {
      $doMaximize = [bool]$cfg.options.maximizeWindow
    }
    if ($doMaximize) {
      Write-Step "  maximize store window..."
      try { Maximize-ZiniaoBrowserWindows } catch { Write-Step ("  WARN maximize Win32: {0}" -f $_) }
      try {
        $maxJs = '(function(){try{if(window.moveTo)window.moveTo(0,0);if(window.resizeTo)window.resizeTo(screen.availWidth,screen.availHeight);return JSON.stringify({ok:true,w:window.outerWidth||0,h:window.outerHeight||0,sw:screen.availWidth,sh:screen.availHeight})}catch(e){return JSON.stringify({ok:false,error:String(e&&e.message||e)})}})()'
        $maxOut = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $maxJs, '--timeout', '15000')
        Write-Host $maxOut
      } catch {
        Write-Step ("  WARN maximize page exec: {0}" -f $_)
      }
    }

    Write-Step "  visit ads page..."
    # visit may fail (Bridge glitch) while page still usable — soft-log and continue
    $visitOut = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $adsUrl, '--wait-until', 'networkidle', '--timeout', '90000')
    Write-Host $visitOut
    if ($visitOut -match '"ok"\s*:\s*false' -or $visitOut -match 'Bridge|无法连接|network') {
      Write-Step "  WARN page visit soft-failed; will still try scrape after wait"
    }
    if ($doMaximize) {
      try { Maximize-ZiniaoBrowserWindows } catch { }
    }
    Start-Sleep -Milliseconds ([int]$cfg.options.waitAfterVisitMs)

    $rawRows = @()
    $lastErr = $null
    for ($attempt = 1; $attempt -le $scrapeRetries; $attempt++) {
      Write-Step ("  page exec scrape (attempt {0}/{1})..." -f $attempt, $scrapeRetries)
      $execOut = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $scrapeOneLine, '--timeout', '60000')
      Write-Host $execOut

      $payload = Get-ScrapePayload $execOut
      if (-not $payload) {
        $lastErr = 'scrape failed: empty payload'
        Write-Step ("  attempt {0}: {1}" -f $attempt, $lastErr)
      } elseif (-not $payload.ok) {
        $lastErr = Get-FriendlyScrapeError $payload $(if ($payload.error) { [string]$payload.error } else { 'scrape failed (ok=false)' })
        # Hard fail: verification page won't fix by waiting
        if ($payload.url -and ([string]$payload.url -match 'settle/verification|verification')) {
          break
        }
        Write-Step ("  attempt {0}: {1}" -f $attempt, $lastErr)
      } else {
        $rawRows = @()
        if ($null -ne $payload.rows) {
          if ($payload.rows -is [System.Array]) { $rawRows = @($payload.rows) }
          else { $rawRows = @($payload.rows) }
        }
        $rawRows = @($rawRows | Where-Object { $_ -and ($_.campaign -or $null -ne $_.spend -or $null -ne $_.revenue) })
        if ($rawRows.Count -gt 0) {
          $lastErr = $null
          break
        }
        # On ads dashboard but 0 data rows — likely still loading
        $lastErr = Get-FriendlyScrapeError $payload '广告页已打开但表格 0 行（可能仍在加载）'
        Write-Step ("  attempt {0}: {1}" -f $attempt, $lastErr)
      }

      if ($attempt -lt $scrapeRetries) {
        Write-Step ("  retry wait {0}ms + re-visit..." -f $scrapeRetryWaitMs)
        Start-Sleep -Milliseconds $scrapeRetryWaitMs
        $null = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $adsUrl, '--wait-until', 'networkidle', '--timeout', '90000')
        Start-Sleep -Milliseconds ([Math]::Min([int]$cfg.options.waitAfterVisitMs, 15000))
      }
    }

    if ($lastErr -or $rawRows.Count -eq 0) {
      $errMsg = if ($lastErr) { $lastErr } else { '广告表格 0 行' }
      $null = Save-ScrapeDebug -StoreId $sid -StoreName $sname -DisplayName $display -AdsUrl $adsUrl `
        -ExecOut $execOut -Payload $payload -ErrorMsg $errMsg
      $debugSaved = $true
      throw $errMsg
    }

    # 页面币种：抓取脚本检测符号；未识别时用 pageDefault（默认 USD，与广告后台一致）
    $pageCurrency = $currencyCfg.pageDefault
    if ($payload.currency) {
      $pageCurrency = ([string]$payload.currency).ToUpperInvariant()
    }
    $targetCurrency = $currencyCfg.target
    $needConvert = $currencyCfg.convert -and ($pageCurrency -ne $targetCurrency)
    if ($needConvert) {
      Write-Step ("  currency convert {0} -> {1} (ratesToUsd.{0}={2})" -f `
        $pageCurrency, $targetCurrency, $currencyCfg.ratesToUsd[$pageCurrency])
    } else {
      Write-Step ("  currency={0} (no convert; spend/revenue as {1})" -f $pageCurrency, $targetCurrency)
    }

    $rows = @()
    $skippedDisabled = 0
    foreach ($r in $rawRows) {
      $spendRaw = 0.0
      if ($null -ne $r.spend) { $spendRaw = [double]$r.spend }
      $revenueRaw = 0.0
      if ($null -ne $r.revenue) { $revenueRaw = [double]$r.revenue }
      $spendOut = $spendRaw
      $revenueOut = $revenueRaw
      if ($needConvert) {
        $spendOut = Convert-MoneyToTarget -Amount $spendRaw -FromCurrency $pageCurrency `
          -TargetCurrency $targetCurrency -RatesToUsd $currencyCfg.ratesToUsd
        $revenueOut = Convert-MoneyToTarget -Amount $revenueRaw -FromCurrency $pageCurrency `
          -TargetCurrency $targetCurrency -RatesToUsd $currencyCfg.ratesToUsd
      } else {
        $spendOut = [math]::Round($spendRaw, 2)
        $revenueOut = [math]::Round($revenueRaw, 2)
      }
      $planStatus = Normalize-PlanStatus $r.planStatus
      $candidate = [pscustomobject]@{
        date         = $bizDate
        store        = $display
        storeId      = $sid
        campaign     = [string]$r.campaign
        spend        = $spendOut
        orders       = if ($null -ne $r.orders) { $r.orders } else { 0 }
        roi          = if ($null -ne $r.roi) { $r.roi } else { 0 }
        revenue      = $revenueOut
        currency     = $targetCurrency
        pageCurrency = $pageCurrency
        sourceUrl    = [string]$payload.url
        status       = 'success'
        planStatus   = $planStatus
      }
      if ($skipZeroDisabled -and (Test-SkipZeroDisabledCampaign $candidate)) {
        $skippedDisabled++
        Write-Step ("  skip closed+zero: {0} (planStatus=off spend=0 revenue=0)" -f $candidate.campaign)
        continue
      }
      $rows += $candidate
    }
    if ($skippedDisabled -gt 0) {
      Write-Step ("  filtered {0} closed zero-metric campaign(s)" -f $skippedDisabled)
    }
    $item.rows = $rows.Count
    if ($rows.Count -gt 0) { $allCampaignRows += $rows }

    # --- Stage A: 旁路上报清泉中心（failOpen，默认不阻断飞书）---
    $writeMode = 'direct'
    if (Get-Command Get-FeishuWriteMode -ErrorAction SilentlyContinue) {
      $writeMode = Get-FeishuWriteMode $cfg
    }
    $qingquanEnabled = $false
    if ($cfg.qingquan -and $null -ne $cfg.qingquan.enabled) { $qingquanEnabled = [bool]$cfg.qingquan.enabled }

    if ($qingquanEnabled -and (Get-Command Send-QingquanIngest -ErrorAction SilentlyContinue)) {
      if ($useDryRun) {
        Write-Step ("  qingquan dryRun: would report {0} rows (writeMode={1}, currency={2})" -f $rows.Count, $writeMode, $targetCurrency)
      } else {
        $collectedAt = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss+00:00')
        $qqItems = ConvertTo-QingquanIngestItems -Rows $rows -CollectedAt $collectedAt -Currency $targetCurrency
        Write-Step ("  report Qingquan center ({0} items, writeMode={1}, currency={2})..." -f $qqItems.Count, $writeMode, $targetCurrency)
        $qq = Send-QingquanIngest -Config $cfg -Items $qqItems
        $item.qingquanAccepted = $qq.accepted
        $item.qingquanDup = $qq.duplicated
        if ($qq.error) { $item.qingquanError = [string]$qq.error }
        Write-Step ("  qingquan accepted={0} duplicated={1} failed={2} ok={3}" -f $qq.accepted, $qq.duplicated, $qq.failed, $qq.ok)
      }
    }

    # direct / dual → 写飞书；center → 仅中心（飞书由中心同步）
    $shouldWriteFeishu = ($writeMode -ne 'center')
    if ($shouldWriteFeishu) {
      Write-Step ("  scraped {0} rows (source={1}), write Feishu..." -f $rows.Count, $payload.source)
      $w = Write-FeishuRows $cfg.feishu $rows $useDryRun
      $item.written = $w.written
      Write-Step ("  done written={0}" -f $w.written)
    } else {
      Write-Step ("  scraped {0} rows (source={1}), skip Feishu direct write (writeMode=center)" -f $rows.Count, $payload.source)
      $item.written = 0
    }
    $item.ok = $true
    $null = Save-ScrapeDebug -StoreId $sid -StoreName $sname -DisplayName $display -AdsUrl $adsUrl `
      -ExecOut $execOut -Payload $payload -ErrorMsg $null -AsLast
    $debugSaved = $true
  }
  catch {
    $item.error = [string]$_
    Write-Step ("  FAIL: {0}" -f $_)
    if (-not $debugSaved) {
      try {
        $null = Save-ScrapeDebug -StoreId $sid -StoreName $sname -DisplayName $display -AdsUrl $adsUrl `
          -ExecOut $execOut -Payload $payload -ErrorMsg ([string]$_)
      } catch {
        Write-Step ("  debug save failed: {0}" -f $_)
      }
    }
  }
  finally {
    if ($cfg.options.closeAfter) {
      try {
        Write-Step "  close store..."
        $null = Invoke-Ziniao @('store', 'close', '--id', $sid)
      } catch { }
    }
    Start-Sleep -Milliseconds ([int]$cfg.options.delayBetweenStoresMs)
  }
  $summary += [pscustomobject]$item
}

Write-Step "======== SUMMARY ========"
$summary | Format-Table storeName, displayName, ok, rows, written, qingquanAccepted, qingquanDup, error -AutoSize
$okCount = @($summary | Where-Object { $_.ok }).Count
Write-Step ("OK {0} / {1}" -f $okCount, $summary.Count)
$qqFail = @($summary | Where-Object { $_.qingquanError }).Count
if ($qqFail -gt 0) {
  Write-Step ("NOTE: qingquan report soft-failed on {0} store(s) (failOpen; Feishu path unaffected if writeMode!=center)" -f $qqFail)
}
$outPath = Join-Path $root ("logs\multi-store-{0:yyyyMMdd-HHmmss}.json" -f (Get-Date))
New-Item -ItemType Directory -Force -Path (Split-Path $outPath) | Out-Null
$summary | ConvertTo-Json -Depth 6 | Set-Content $outPath -Encoding UTF8
Write-Step ("log: {0}" -f $outPath)

# --- daily analysis (saved under 日报/ for easy browsing; logs/ keeps scrape debug only) ---
if ($analysisEnabled -and (Get-Command Build-DailyAnalysis -ErrorAction SilentlyContinue)) {
  try {
    Write-Step "build daily analysis..."
    $analysis = Build-DailyAnalysis -CampaignRows $allCampaignRows -RunSummary $summary -BizDate $bizDate -LowRoiThreshold $lowRoi
    $reportDir = Join-Path $root '日报'
    New-Item -ItemType Directory -Force -Path $reportDir | Out-Null
    $mdPath = Join-Path $reportDir ("日报-{0}.md" -f $bizDate)
    $analysis.markdown | Set-Content -Path $mdPath -Encoding UTF8
    $briefPath = Join-Path $reportDir ("简报-{0}.txt" -f $bizDate)
    $analysis.briefText | Set-Content -Path $briefPath -Encoding UTF8
    $analysisJson = Join-Path $reportDir ("日报-{0}.json" -f $bizDate)
    [pscustomobject]@{
      bizDate        = $analysis.bizDate
      totalSpend     = $analysis.totalSpend
      totalOrders    = $analysis.totalOrders
      totalRevenue   = $analysis.totalRevenue
      totalCampaigns = $analysis.totalCampaigns
      overallRoi     = $analysis.overallRoi
      highlights     = $analysis.highlights
      risks          = $analysis.risks
      storeRollups   = $analysis.storeRollups
    } | ConvertTo-Json -Depth 6 | Set-Content $analysisJson -Encoding UTF8
    # One-click latest aliases
    Copy-Item -LiteralPath $mdPath -Destination (Join-Path $reportDir '最新日报.md') -Force
    Copy-Item -LiteralPath $briefPath -Destination (Join-Path $reportDir '最新简报.txt') -Force
    Write-Step ("日报目录: {0}" -f $reportDir)
    Write-Step ("analysis md: {0}" -f $mdPath)
    Write-Host ""
    Write-Host $analysis.briefText
    Write-Host ""
    if ($analysis.storeRollups.Count -gt 0) {
      $analysis.storeRollups | Format-Table store, campaigns, spend, orders, revenue, roi, topCampaign -AutoSize
    }

    if ($writeSummaryFeishu) {
      $sumRows = New-SummaryFeishuRows -Analysis $analysis -BizDate $bizDate
      Write-Step ("write summary rows to Feishu: {0}" -f $sumRows.Count)
      $sw = Write-FeishuRows $cfg.feishu $sumRows $useDryRun
      Write-Step ("summary written={0} dryRun={1}" -f $sw.written, $sw.dryRun)
    }
  }
  catch {
    Write-Step ("analysis FAILED (non-fatal): {0}" -f $_)
  }
}

if ($okCount -lt $summary.Count) { exit 2 }

extension\\scraper\\parse-api.js.content:
/**
 * 从拦截到的报表 API JSON 中抽取广告系列字段
 * 结构因接口而异，做多层启发式遍历
 */

import { cleanText, parseNumber } from './normalize.js';

const KEY_MAP = {
  campaign: [
    'campaign_name',
    'campaignName',
    'ad_name',
    'adName',
    'name',
    'title',
    'product_name',
    'productName',
    'creative_name'
  ],
  spend: [
    'spend',
    'cost',
    'ad_spend',
    'adSpend',
    'stat_cost',
    'statCost',
    'amount_spent',
    'consume'
  ],
  orders: [
    'orders',
    'order_count',
    'orderCount',
    'units',
    'units_sold',
    'unitsSold',
    'paid_order_count',
    'conversions',
    'onsite_shopping'
  ],
  roi: ['roi', 'roas', 'ROI', 'ROAS', 'complete_payment_roas', 'onsite_roas'],
  revenue: [
    'revenue',
    'gmv',
    'gross_revenue',
    'grossRevenue',
    'total_revenue',
    'onsite_shopping_value',
    'complete_payment',
    'sales',
    'income'
  ],
  planStatus: [
    'status',
    'opt_status',
    'optStatus',
    'operation_status',
    'operationStatus',
    'campaign_status',
    'campaignStatus',
    'enable',
    'enabled',
    'is_enable',
    'isEnable',
    'switch_status',
    'switchStatus'
  ]
};

/**
 * @param {unknown} payload
 * @returns {object[]}
 */
export function parseApiPayload(payload) {
  if (payload == null) return [];
  let data = payload;
  if (typeof payload === 'string') {
    try {
      data = JSON.parse(payload);
    } catch {
      return [];
    }
  }

  const list = findArrayOfObjects(data);
  if (!list.length) return [];

  const rows = [];
  for (const item of list) {
    if (!item || typeof item !== 'object') continue;
    const row = extractRow(item);
    if (row.campaign || row.spend != null || row.revenue != null) {
      rows.push(row);
    }
  }
  return rows;
}

function normalizeApiPlanStatus(v) {
  if (v == null || v === '') return null;
  if (typeof v === 'boolean') return v ? 'on' : 'off';
  if (typeof v === 'number') {
    if (v === 1) return 'on';
    if (v === 0) return 'off';
  }
  const s = String(v).trim().toLowerCase();
  if (/^(on|1|true|enable|enabled|open|active|running|delivery_ok|campaign_status_enable)$/i.test(s)) {
    return 'on';
  }
  if (
    /^(off|0|false|disable|disabled|close|closed|paused|inactive|campaign_status_disable|campaign_status_delete)$/i.test(
      s
    )
  ) {
    return 'off';
  }
  return null;
}

function extractRow(obj) {
  const flat = flattenObject(obj);
  const row = {};
  for (const [field, keys] of Object.entries(KEY_MAP)) {
    for (const k of keys) {
      if (flat[k] != null && flat[k] !== '') {
        if (field === 'campaign') row[field] = cleanText(flat[k]);
        else if (field === 'planStatus') row[field] = normalizeApiPlanStatus(flat[k]) || flat[k];
        else row[field] = parseNumber(flat[k]) ?? flat[k];
        break;
      }
    }
    // 大小写不敏感扫一遍
    if (row[field] == null) {
      const lowerKeys = Object.keys(flat);
      for (const k of keys) {
        const hit = lowerKeys.find((x) => x.toLowerCase() === k.toLowerCase());
        if (hit && flat[hit] != null && flat[hit] !== '') {
          if (field === 'campaign') row[field] = cleanText(flat[hit]);
          else if (field === 'planStatus') {
            row[field] = normalizeApiPlanStatus(flat[hit]) || flat[hit];
          } else row[field] = parseNumber(flat[hit]) ?? flat[hit];
          break;
        }
      }
    }
  }
  return row;
}

/**
 * 扁平化一层 metrics / stats 嵌套
 */
function flattenObject(obj, prefix = '', out = {}, depth = 0) {
  if (!obj || typeof obj !== 'object' || depth > 4) return out;
  for (const [k, v] of Object.entries(obj)) {
    const key = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      // 保留浅 key
      out[k] = out[k] ?? (typeof v.value !== 'undefined' ? v.value : undefined);
      flattenObject(v, key, out, depth + 1);
      // metrics 常见 { value: 1 }
      if (v.value != null) out[k] = v.value;
    } else if (!Array.isArray(v)) {
      out[k] = v;
      out[key] = v;
    }
  }
  return out;
}

/**
 * 在 JSON 树中找「最像报表行」的对象数组
 * @param {unknown} data
 * @returns {object[]}
 */
function findArrayOfObjects(data, depth = 0) {
  if (depth > 8 || data == null) return [];
  if (Array.isArray(data)) {
    const objs = data.filter((x) => x && typeof x === 'object' && !Array.isArray(x));
    if (objs.length >= 1 && looksLikeReportRows(objs)) return objs;
    // 继续往子项挖
    for (const item of data.slice(0, 20)) {
      const found = findArrayOfObjects(item, depth + 1);
      if (found.length) return found;
    }
    if (objs.length >= 1) return objs;
    return [];
  }
  if (typeof data === 'object') {
    // 优先常见字段
    const prefer = [
      'list',
      'rows',
      'data',
      'items',
      'records',
      'campaigns',
      'result',
      'table'
    ];
    for (const k of prefer) {
      if (data[k] != null) {
        const found = findArrayOfObjects(data[k], depth + 1);
        if (found.length) return found;
      }
    }
    for (const v of Object.values(data)) {
      const found = findArrayOfObjects(v, depth + 1);
      if (found.length) return found;
    }
  }
  return [];
}

function looksLikeReportRows(objs) {
  const sample = objs.slice(0, 5);
  let hits = 0;
  for (const o of sample) {
    const keys = Object.keys(o).join(' ').toLowerCase();
    if (/campaign|spend|cost|roi|roas|gmv|revenue|order|name/.test(keys)) hits += 1;
    // nested metrics
    if (o.metrics || o.stats || o.stat) hits += 1;
  }
  return hits >= 1;
}

/**
 * URL 是否可能是报表接口
 * @param {string} url
 */
export function isLikelyReportUrl(url) {
  if (!url) return false;
  const u = url.toLowerCase();
  return /report|stat|metric|campaign|gmv|ads?\/api|shop_ads|analytics|performance|overview|data_list|getlist/.test(
    u
  );
}

scripts\\qingquan-client.ps1.content:
# 清泉中心 Ingest 客户端（Stage A 旁路）
# 由 run-multi-store.ps1 dot-source 使用；也可单独点测。
#
# 依赖 config.qingquan:
# {
#   "enabled": true,
#   "baseUrl": "http://127.0.0.1:8000",
#   "apiKey": "dev-ingest-key",
#   "source": "tiktok_ads",
#   "failOpen": true,
#   "timeoutSec": 30
# }

function Get-QingquanConfig($cfg) {
  if (-not $cfg.qingquan) {
    return [pscustomobject]@{
      enabled    = $false
      baseUrl    = 'http://127.0.0.1:8000'
      apiKey     = ''
      source     = 'tiktok_ads'
      failOpen   = $true
      timeoutSec = 30
    }
  }
  $q = $cfg.qingquan
  $enabled = $false
  if ($null -ne $q.enabled) { $enabled = [bool]$q.enabled }
  $failOpen = $true
  if ($null -ne $q.failOpen) { $failOpen = [bool]$q.failOpen }
  $timeout = 30
  if ($null -ne $q.timeoutSec) { $timeout = [int]$q.timeoutSec }
  $source = 'tiktok_ads'
  if ($q.source) { $source = [string]$q.source }
  $base = 'http://127.0.0.1:8000'
  if ($q.baseUrl) { $base = [string]$q.baseUrl }
  $key = ''
  if ($q.apiKey) { $key = [string]$q.apiKey }
  return [pscustomobject]@{
    enabled    = $enabled
    baseUrl    = $base.TrimEnd('/')
    apiKey     = $key
    source     = $source
    failOpen   = $failOpen
    timeoutSec = $timeout
  }
}

function Get-FeishuWriteMode($cfg) {
  # direct | dual | center
  $mode = 'direct'
  if ($cfg.feishu -and $cfg.feishu.writeMode) {
    $mode = [string]$cfg.feishu.writeMode
  } elseif ($cfg.qingquan -and $cfg.qingquan.enabled) {
    # 启用清泉但未写 writeMode 时，Stage A 默认 dual
    $mode = 'dual'
  }
  $mode = $mode.ToLowerInvariant()
  if ($mode -notin @('direct', 'dual', 'center')) { $mode = 'direct' }
  return $mode
}

function ConvertTo-QingquanIngestItems {
  param(
    [Parameter(Mandatory = $true)] $Rows,
    [Parameter(Mandatory = $true)] [string]$CollectedAt,
    [string]$Currency = 'USD'
  )
  if ([string]::IsNullOrWhiteSpace($Currency)) { $Currency = 'USD' }
  $items = @()
  foreach ($r in @($Rows)) {
    $campaign = [string]$r.campaign
    if (-not $campaign) { continue }
    $storeId = [string]$r.storeId
    $bizDate = [string]$r.date
    $spend = 0; if ($null -ne $r.spend) { $spend = [double]$r.spend }
    $orders = 0; if ($null -ne $r.orders) { $orders = [double]$r.orders }
    $roi = $null; if ($null -ne $r.roi) { $roi = [double]$r.roi }
    $revenue = 0; if ($null -ne $r.revenue) { $revenue = [double]$r.revenue }
    $status = 'success'; if ($r.status) { $status = [string]$r.status }
    $planStatus = ''; if ($r.planStatus) { $planStatus = [string]$r.planStatus }
    $sourceUrl = ''; if ($r.sourceUrl) { $sourceUrl = [string]$r.sourceUrl }
    $storeName = ''; if ($r.store) { $storeName = [string]$r.store }
    $rowCurrency = $Currency
    if ($r.currency) { $rowCurrency = [string]$r.currency }

    $items += [ordered]@{
      platform         = 'tiktok'
      shop_id          = $storeId
      shop_name        = $storeName
      biz_date         = $bizDate
      collected_at     = $CollectedAt
      idempotency_key  = ("tiktok_ads:{0}:{1}:{2}" -f $storeId, $campaign, $bizDate)
      payload          = [ordered]@{
        campaign_name = $campaign
        spend         = $spend
        orders        = $orders
        roi           = $roi
        revenue       = $revenue
        row_status    = $status
        plan_status   = $planStatus
        currency      = $rowCurrency
        source_url    = $sourceUrl
      }
      evidence         = [ordered]@{
        source_url = $sourceUrl
      }
    }
  }
  return $items
}

function Send-QingquanIngest {
  param(
    [Parameter(Mandatory = $true)] $Config,
    [Parameter(Mandatory = $true)] $Items,
    [switch]$Quiet
  )
  $q = Get-QingquanConfig $Config
  if (-not $q.enabled) {
    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'qingquan.disabled'; accepted = 0; duplicated = 0; failed = 0 }
  }
  if (-not $q.apiKey) {
    $msg = 'qingquan.apiKey empty'
    if ($q.failOpen) {
      if (-not $Quiet) { Write-Warning $msg }
      return [pscustomobject]@{ ok = $false; skipped = $false; error = $msg; accepted = 0; duplicated = 0; failed = @($Items).Count }
    }
    throw $msg
  }
  if (@($Items).Count -eq 0) {
    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'empty-items'; accepted = 0; duplicated = 0; failed = 0 }
  }

  $url = "{0}/api/v1/ingest/{1}" -f $q.baseUrl, $q.source
  $payload = @{ items = @($Items) }
  $json = $payload | ConvertTo-Json -Depth 10 -Compress
  # PS 5.1 ConvertTo-Json 对中文可能转义；UTF8 字节发送
  $bodyBytes = [System.Text.Encoding]::UTF8.GetBytes($json)

  try {
    $resp = Invoke-RestMethod -Method Post -Uri $url -TimeoutSec $q.timeoutSec -ContentType 'application/json; charset=utf-8' -Body $bodyBytes -Headers @{
      'X-Api-Key' = $q.apiKey
    }
    $accepted = 0; $duplicated = 0; $failed = 0
    if ($null -ne $resp.accepted) { $accepted = [int]$resp.accepted }
    if ($null -ne $resp.duplicated) { $duplicated = [int]$resp.duplicated }
    if ($null -ne $resp.failed) { $failed = [int]$resp.failed }
    return [pscustomobject]@{
      ok         = ($failed -eq 0)
      skipped    = $false
      accepted   = $accepted
      duplicated = $duplicated
      failed     = $failed
      resp       = $resp
      error      = $null
    }
  }
  catch {
    $err = [string]$_
    if ($q.failOpen) {
      if (-not $Quiet) { Write-Warning ("qingquan ingest failed (failOpen): {0}" -f $err) }
      return [pscustomobject]@{
        ok         = $false
        skipped    = $false
        accepted   = 0
        duplicated = 0
        failed     = @($Items).Count
        resp       = $null
        error      = $err
      }
    }
    throw
  }
}

function Test-QingquanHealth {
  param([Parameter(Mandatory = $true)] $Config)
  $q = Get-QingquanConfig $Config
  $url = "{0}/health" -f $q.baseUrl
  try {
    $r = Invoke-RestMethod -Method Get -Uri $url -TimeoutSec 10
    return [pscustomobject]@{ ok = ($r.status -eq 'ok'); resp = $r; error = $null }
  }
  catch {
    return [pscustomobject]@{ ok = $false; resp = $null; error = [string]$_ }
  }
}

extension\\scraper\\parse-table.js.content:
/**
 * DOM 表格解析：按表头语义匹配列，抽取广告系列行
 * 避免依赖哈希 class，适配 TikTok Seller / Ads 改版
 */

import { HEADER_ALIASES } from '../lib/constants.js';
import { cleanText, parseNumber } from './normalize.js';

/**
 * 判断表头文本属于哪个业务字段
 * @param {string} headerText
 * @returns {keyof typeof HEADER_ALIASES|null}
 */
export function matchHeaderField(headerText) {
  const t = cleanText(headerText).toLowerCase();
  if (!t) return null;

  // 优先更具体的匹配（开关 / roi 先于宽泛词）
  const order = ['planStatus', 'roi', 'spend', 'orders', 'revenue', 'campaign'];
  for (const field of order) {
    const aliases = HEADER_ALIASES[field];
    if (!aliases) continue;
    for (const a of aliases) {
      const al = a.toLowerCase();
      if (!(t === al || t.includes(al) || (al.length >= 2 && al.includes(t)))) continue;
      if (field === 'planStatus') {
        if (/投放状态|计划状态|delivery|operation status/.test(t)) return field;
        if (t === al || t === '开关' || t === 'switch' || t === 'enable' || t === 'enabled') {
          return field;
        }
        if (/开关|switch|toggle|on\/off/.test(t) && t.length <= 12) return field;
        continue;
      }
      if (field === 'spend') {
        if (/平均下单|cost per|per order|\bcpc\b|\bcpa\b|\bcpm\b/.test(t)) continue;
        if (
          t.includes('budget') &&
          !t.includes('spent') &&
          !t.includes('spend') &&
          !t.includes('cost') &&
          !t.includes('成本')
        ) {
          continue;
        }
      }
      if (field === 'campaign' && (al === '名称' || al === 'name')) {
        if (
          !/系列|campaign|广告|活动|product|品名|计划/.test(t) &&
          t !== '名称' &&
          t !== 'name'
        ) {
          continue;
        }
      }
      return field;
    }
  }
  return null;
}

/**
 * 从单元格 / 行 DOM 识别开关 on|off
 * @param {Element|null} el
 * @returns {'on'|'off'|null}
 */
export function parseSwitchFromEl(el) {
  if (!el) return null;
  const input = el.matches?.('input')
    ? el
    : el.querySelector?.('input[type="checkbox"], input[role="switch"]');
  if (input) {
    const aria = input.getAttribute('aria-checked');
    if (aria === 'true') return 'on';
    if (aria === 'false') return 'off';
    return input.checked ? 'on' : 'off';
  }
  const sw =
    (el.matches?.('[role="switch"], [class*="switch"], [class*="Switch"]') && el) ||
    el.querySelector?.(
      '[role="switch"], [class*="switch"], [class*="Switch"], [class*="toggle"]'
    );
  if (sw) {
    const aria = sw.getAttribute('aria-checked');
    if (aria === 'true') return 'on';
    if (aria === 'false') return 'off';
    const cls = `${sw.className || ''} ${sw.parentElement?.className || ''}`;
    if (
      /\b(checked|is-checked|switch-checked|arco-switch-checked|ant-switch-checked|is-on)\b/i.test(
        cls
      )
    ) {
      return 'on';
    }
    if (/\b(unchecked|is-unchecked|is-off)\b/i.test(cls)) return 'off';
  }
  const text = cleanText((el.innerText || el.textContent || '').slice(0, 40));
  if (/^(开|开启|on|enable|enabled|投放中|投放)$/i.test(text)) return 'on';
  if (/^(关|关闭|off|disable|disabled|已关闭|暂停)$/i.test(text)) return 'off';
  return null;
}

/**
 * @param {Element} tr
 * @param {Element[]} cells
 * @param {number|null} switchColIndex
 */
export function detectPlanStatusFromRow(tr, cells, switchColIndex) {
  if (switchColIndex != null && cells[switchColIndex]) {
    const s = parseSwitchFromEl(cells[switchColIndex]);
    if (s) return s;
  }
  for (const cell of cells) {
    const s = parseSwitchFromEl(cell);
    if (s) return s;
  }
  const sTr = parseSwitchFromEl(tr);
  return sTr || 'unknown';
}

/**
 * 从 thead / 首行收集表头
 * @param {HTMLTableElement} table
 * @returns {{cells: Element[], fields: (string|null)[]}}
 */
export function extractTableHeaders(table) {
  let headerRow = table.querySelector('thead tr');
  if (!headerRow) {
    headerRow = table.querySelector('tr');
  }
  if (!headerRow) return { cells: [], fields: [] };

  const cells = [...headerRow.querySelectorAll('th, td')];
  const fields = cells.map((c) => matchHeaderField(c.innerText || c.textContent || ''));
  return { cells, fields };
}

/**
 * 解析原生 HTML table
 * @param {HTMLTableElement} table
 * @returns {object[]}
 */
export function parseHtmlTable(table) {
  const { fields } = extractTableHeaders(table);
  if (!fields.some(Boolean)) return [];

  let switchColIndex = fields.indexOf('planStatus');
  if (switchColIndex < 0) switchColIndex = null;

  const bodyRows = table.querySelectorAll('tbody tr');
  const rows = bodyRows.length
    ? [...bodyRows]
    : [...table.querySelectorAll('tr')].slice(1);

  const results = [];
  for (const tr of rows) {
    const cells = [...tr.querySelectorAll('td, th')];
    if (!cells.length) continue;
    const row = {};
    fields.forEach((field, i) => {
      if (!field || !cells[i]) return;
      if (field === 'planStatus') {
        row.planStatus = parseSwitchFromEl(cells[i]) || 'unknown';
        return;
      }
      const text = cleanText(cells[i].innerText || cells[i].textContent || '');
      row[field] = text;
    });
    if (!row.planStatus) {
      row.planStatus = detectPlanStatusFromRow(tr, cells, switchColIndex);
    }
    if (Object.keys(row).length) results.push(row);
  }
  return results;
}

/**
 * 解析 div / role=table 的网格（常见于 Ant Design / 自定义表格）
 * @param {Element} root
 * @returns {object[]}
 */
export function parseRoleTable(root) {
  const headerCells = [
    ...root.querySelectorAll(
      '[role="columnheader"], .ant-table-thead th, [class*="table-header"] th, [class*="TableHeader"]'
    )
  ];
  if (!headerCells.length) return [];

  const fields = headerCells.map((c) =>
    matchHeaderField(c.innerText || c.textContent || '')
  );
  if (!fields.some(Boolean)) return [];

  const dataRows = [
    ...root.querySelectorAll(
      '[role="row"]:not(:has([role="columnheader"])), .ant-table-tbody tr, tbody tr'
    )
  ].filter((r) => r.querySelectorAll('[role="cell"], td').length);

  let switchColIndex = fields.indexOf('planStatus');
  if (switchColIndex < 0) switchColIndex = null;

  const results = [];
  for (const tr of dataRows) {
    const cells = [...tr.querySelectorAll('[role="cell"], td')];
    if (!cells.length) continue;
    const row = {};
    fields.forEach((field, i) => {
      if (!field || !cells[i]) return;
      if (field === 'planStatus') {
        row.planStatus = parseSwitchFromEl(cells[i]) || 'unknown';
        return;
      }
      row[field] = cleanText(cells[i].innerText || cells[i].textContent || '');
    });
    if (!row.planStatus) {
      row.planStatus = detectPlanStatusFromRow(tr, cells, switchColIndex);
    }
    if (Object.keys(row).length) results.push(row);
  }
  return results;
}

/**
 * 启发式：页面上所有表格，取「匹配字段最多且行数最多」的一份
 * @param {Document} doc
 * @returns {{rows: object[], source: string}}
 */
export function scrapeTablesFromDocument(doc = document) {
  const candidates = [];

  const tables = [...doc.querySelectorAll('table')];
  for (const table of tables) {
    const rows = parseHtmlTable(table);
    const score = scoreRows(rows);
    if (score > 0) {
      candidates.push({ rows, score, source: 'html-table' });
    }
  }

  // 常见容器
  const containers = [
    ...doc.querySelectorAll(
      '.ant-table, [class*="Table"], [class*="data-table"], [role="table"], [class*="campaign"]'
    )
  ];
  for (const el of containers) {
    const rows = parseRoleTable(el);
    const score = scoreRows(rows);
    if (score > 0) {
      candidates.push({ rows, score, source: 'role-table' });
    }
  }

  // 无 table 时：扫描「看起来像表头」的横向列表
  if (!candidates.length) {
    const heuristic = heuristicGridScan(doc);
    if (heuristic.rows.length) candidates.push({ ...heuristic, source: 'heuristic' });
  }

  candidates.sort((a, b) => b.score - a.score);
  if (!candidates.length) {
    return { rows: [], source: 'none' };
  }
  return { rows: candidates[0].rows, source: candidates[0].source };
}

function scoreRows(rows) {
  if (!rows?.length) return 0;
  let score = rows.length;
  const sample = rows.slice(0, 5);
  for (const r of sample) {
    if (r.campaign) score += 2;
    if (r.spend != null && r.spend !== '') score += 2;
    if (r.roi != null && r.roi !== '') score += 2;
    if (r.revenue != null && r.revenue !== '') score += 2;
    if (r.orders != null && r.orders !== '') score += 1;
  }
  return score;
}

/**
 * 弱启发：找含多个表头关键词的行，下一行起当数据
 * @param {Document} doc
 */
function heuristicGridScan(doc) {
  const all = [...doc.querySelectorAll('div, tr, li')].slice(0, 2000);
  for (const el of all) {
    const children = [...el.children];
    if (children.length < 3 || children.length > 20) continue;
    const texts = children.map((c) => cleanText(c.innerText || '').slice(0, 40));
    const fields = texts.map(matchHeaderField);
    const hit = fields.filter(Boolean).length;
    if (hit < 3) continue;

    // 同级后续兄弟中找相似结构
    const parent = el.parentElement;
    if (!parent) continue;
    const siblings = [...parent.children];
    const start = siblings.indexOf(el);
    const rows = [];
    for (let i = start + 1; i < Math.min(siblings.length, start + 200); i++) {
      const cells = [...siblings[i].children];
      if (cells.length < 2) continue;
      const row = {};
      fields.forEach((field, idx) => {
        if (!field || !cells[idx]) return;
        row[field] = cleanText(cells[idx].innerText || '');
      });
      if (row.campaign || row.spend || row.revenue) rows.push(row);
    }
    if (rows.length >= 1) {
      return { rows, score: scoreRows(rows) };
    }
  }
  return { rows: [], score: 0 };
}

/**
 * 尝试从页面探测店铺名
 * @param {Document} doc
 */
export function detectStoreName(doc = document) {
  const title = cleanText(doc.title || '');
  // 常见：Shop name - TikTok ...
  const parts = title.split(/[-|–—]/).map(cleanText).filter(Boolean);
  if (parts.length >= 2) {
    // 去掉纯品牌词
    const skip = /tiktok|seller|ads|shop ads|campaign|dashboard/i;
    for (const p of parts) {
      if (!skip.test(p) && p.length > 1 && p.length < 80) return p;
    }
  }

  // meta / 侧栏
  const candidates = [
    ...doc.querySelectorAll(
      '[class*="shop-name"], [class*="store-name"], [class*="seller-name"], [data-e2e*="shop"]'
    )
  ];
  for (const el of candidates) {
    const t = cleanText(el.innerText || '');
    if (t && t.length < 80) return t;
  }
  return '';
}

// re-export for content script convenience
export { parseNumber };

