/* TikTok ads dashboard scraper for ziniao-cli page exec. No // comments (minified to one line). */
(function () {
  function cleanText(t) {
    return String(t ?? '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function detectCurrency(text) {
    const s = String(text ?? '');
    if (/[£]|GBP|英镑/i.test(s)) return 'GBP';
    if (/[€]|EUR|欧元/i.test(s)) return 'EUR';
    if (/[¥￥]|CNY|RMB|元/i.test(s) && !/\$/.test(s)) return 'CNY';
    if (/\$|USD|美金|美元/i.test(s)) return 'USD';
    return null;
  }

  function parseNumber(value) {
    if (value == null || value === '') return null;
    if (typeof value === 'number' && Number.isFinite(value)) return value;
    let s = String(value).trim();
    if (!s || s === '-' || s === '—') return null;
    s = s
      .replace(/[,\s]/g, '')
      .replace(/[¥$€£￥]/g, '')
      .replace(/USD|GBP|EUR|CNY|RMB|美金|美元|英镑|欧元/gi, '')
      .replace(/%/g, '');
    const paren = s.match(/^\((.+)\)$/);
    if (paren) s = `-${paren[1]}`;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  }

  const HEADER_ALIASES = {
    planStatus: ['开关', '投放开关', 'enable', 'enabled', 'switch', 'on/off', 'toggle'],
    campaign: [
      '品名',
      '广告计划名称',
      '广告系列',
      '广告系列名称',
      '系列名称',
      'campaign',
      'campaign name',
      'product',
      '名称'
    ],
    spend: ['广告花费', '广告成本', '花费', '成本', '消耗', 'cost', 'spend', 'ad spend'],
    orders: [
      '销量',
      '订单',
      'sku 订单',
      'sku订单',
      'sku 订单数',
      'sku订单数',
      'orders',
      'units',
      'units sold'
    ],
    roi: ['roi', 'roas', '投资回报率', '投资回报', '回报率'],
    revenue: ['销售额', '总收入', '销售收入', '收入', 'gmv', 'revenue', 'gross revenue']
  };

  function matchHeaderField(headerText) {
    const t = cleanText(headerText).toLowerCase();
    if (!t) return null;
    const order = ['planStatus', 'roi', 'spend', 'orders', 'revenue', 'campaign'];
    for (const field of order) {
      for (const a of HEADER_ALIASES[field]) {
        const al = a.toLowerCase();
        if (!(t === al || t.includes(al) || (al.length >= 2 && al.includes(t)))) continue;
        if (field === 'spend' && /平均下单|cost per|per order|\bcpc\b|\bcpa\b/.test(t)) continue;
        if (field === 'planStatus') {
          if (/投放状态|计划状态|delivery|operation status/.test(t)) return field;
          if (t === al || t === '开关' || t === 'switch' || t === 'enable' || t === 'enabled') {
            return field;
          }
          if (/开关|switch|toggle|on\/off/.test(t) && t.length <= 12) return field;
          continue;
        }
        if (field === 'campaign' && (al === '名称' || al === 'name')) {
          if (!/系列|campaign|广告|活动|product|品名|计划/.test(t) && t !== '名称' && t !== 'name') {
            continue;
          }
        }
        return field;
      }
    }
    return null;
  }

  function parseSwitchFromEl(el) {
    if (!el) return null;
    const input = el.matches && el.matches('input')
      ? el
      : el.querySelector && el.querySelector('input[type="checkbox"], input[role="switch"]');
    if (input) {
      const aria = input.getAttribute('aria-checked');
      if (aria === 'true') return 'on';
      if (aria === 'false') return 'off';
      return input.checked ? 'on' : 'off';
    }
    const sw =
      (el.matches &&
        el.matches('[role="switch"], [class*="switch"], [class*="Switch"]') &&
        el) ||
      (el.querySelector &&
        el.querySelector(
          '[role="switch"], [class*="switch"], [class*="Switch"], [class*="toggle"], [class*="Toggle"]'
        ));
    if (sw) {
      const aria = sw.getAttribute('aria-checked');
      if (aria === 'true') return 'on';
      if (aria === 'false') return 'off';
      const cls = String(sw.className || '') + ' ' + String(sw.parentElement && sw.parentElement.className || '');
      if (
        /\b(checked|is-checked|switch-checked|arco-switch-checked|ant-switch-checked|is-on|switch_on|active)\b/i.test(
          cls
        )
      ) {
        return 'on';
      }
      if (/\b(unchecked|is-unchecked|switch-disabled|is-off|switch_off)\b/i.test(cls)) {
        return 'off';
      }
      if (sw.getAttribute('data-state') === 'checked' || sw.getAttribute('data-checked') === 'true') {
        return 'on';
      }
      if (sw.getAttribute('data-state') === 'unchecked' || sw.getAttribute('data-checked') === 'false') {
        return 'off';
      }
    }
    const text = cleanText((el.innerText || el.textContent || '').slice(0, 40));
    if (/^(开|开启|on|enable|enabled|投放中|投放|开启中)$/i.test(text)) return 'on';
    if (/^(关|关闭|off|disable|disabled|已关闭|暂停|关闭中)$/i.test(text)) return 'off';
    return null;
  }

  function detectPlanStatusFromRow(tr, cells, switchColIndex) {
    if (switchColIndex != null && cells[switchColIndex]) {
      const s = parseSwitchFromEl(cells[switchColIndex]);
      if (s) return s;
    }
    for (let i = 0; i < cells.length; i++) {
      const s = parseSwitchFromEl(cells[i]);
      if (s) return s;
    }
    const sTr = parseSwitchFromEl(tr);
    if (sTr) return sTr;
    return 'unknown';
  }

  function parseHtmlTable(table) {
    let headerRow = table.querySelector('thead tr') || table.querySelector('tr');
    if (!headerRow) return { rows: [], currencyHits: {} };
    const headerCells = [...headerRow.querySelectorAll('th, td')];
    const fields = headerCells.map((c) => matchHeaderField(c.innerText || ''));
    if (!fields.some(Boolean)) return { rows: [], currencyHits: {} };
    let switchColIndex = fields.indexOf('planStatus');
    if (switchColIndex < 0) switchColIndex = null;
    const bodyRows = table.querySelectorAll('tbody tr');
    const rows = bodyRows.length ? [...bodyRows] : [...table.querySelectorAll('tr')].slice(1);
    const results = [];
    const currencyHits = { USD: 0, GBP: 0, EUR: 0, CNY: 0 };
    for (const tr of rows) {
      const cells = [...tr.querySelectorAll('td, th')];
      if (!cells.length) continue;
      const row = {};
      fields.forEach((field, i) => {
        if (!field || !cells[i]) return;
        if (field === 'planStatus') {
          row.planStatus = parseSwitchFromEl(cells[i]) || 'unknown';
          return;
        }
        const text = cleanText(cells[i].innerText || '');
        if (field === 'campaign') {
          row[field] = text;
          return;
        }
        if (field === 'spend' || field === 'revenue') {
          const cur = detectCurrency(text);
          if (cur && currencyHits[cur] != null) currencyHits[cur] += 1;
        }
        row[field] = parseNumber(text) ?? text;
      });
      if (!row.planStatus) {
        row.planStatus = detectPlanStatusFromRow(tr, cells, switchColIndex);
      }
      if (row.campaign || row.spend != null || row.revenue != null) results.push(row);
    }
    return { rows: results, currencyHits };
  }

  function scoreRows(rows) {
    if (!rows || !rows.length) return 0;
    let s = rows.length;
    for (const r of rows.slice(0, 5)) {
      if (r.campaign) s += 2;
      if (r.spend != null && r.spend !== '') s += 2;
      if (r.roi != null) s += 2;
      if (r.revenue != null) s += 2;
      if (r.planStatus && r.planStatus !== 'unknown') s += 1;
    }
    return s;
  }

  function pickCurrency(hits) {
    let best = null;
    let n = 0;
    for (const k of Object.keys(hits || {})) {
      if (hits[k] > n) {
        n = hits[k];
        best = k;
      }
    }
    return best;
  }

  function detectPageCurrencyHint() {
    const bodyText = cleanText((document.body && document.body.innerText) || '').slice(0, 8000);
    if (/货币|currency|展示币种|金额单位/i.test(bodyText)) {
      const m = bodyText.match(
        /(?:货币|currency|展示币种|金额单位)\s*[:：]?\s*(USD|GBP|EUR|CNY|美金|美元|英镑|欧元)/i
      );
      if (m) {
        const t = m[1].toUpperCase();
        if (t === '美金' || t === '美元') return 'USD';
        if (t === '英镑') return 'GBP';
        if (t === '欧元') return 'EUR';
        return t;
      }
    }
    const sample = bodyText.slice(0, 3000);
    const counts = {
      USD: (sample.match(/\$|USD|美金|美元/gi) || []).length,
      GBP: (sample.match(/£|GBP|英镑/gi) || []).length,
      EUR: (sample.match(/€|EUR|欧元/gi) || []).length
    };
    return pickCurrency(counts);
  }

  let best = [];
  let bestHits = {};
  let source = 'none';
  for (const table of document.querySelectorAll('table')) {
    const parsed = parseHtmlTable(table);
    if (scoreRows(parsed.rows) > scoreRows(best)) {
      best = parsed.rows;
      bestHits = parsed.currencyHits || {};
      source = 'html-table';
    }
  }

  best = best.filter(function (r) {
    const c = cleanText(r.campaign || '').toLowerCase();
    if (!c) return false;
    if (['total', '合计', '总计', '汇总', 'summary', 'all'].indexOf(c) >= 0) return false;
    return true;
  });

  let storeHint = '';
  var els = document.querySelectorAll('div, span, h1, h2');
  for (var i = 0; i < els.length && i < 300; i++) {
    const t = cleanText(els[i].innerText || '');
    if (t.length > 5 && t.length < 100 && /主要账号|主账号/.test(t)) {
      storeHint = t.replace(/主要账号|主账号/g, '').trim();
      break;
    }
  }

  const cellCurrency = pickCurrency(bestHits);
  const pageCurrency = cellCurrency || detectPageCurrencyHint() || 'USD';

  return JSON.stringify({
    ok: best.length > 0,
    source: source,
    storeHint: storeHint,
    currency: pageCurrency,
    currencyHits: bestHits,
    url: location.href,
    title: document.title,
    rows: best,
    error: best.length ? null : '未识别到广告表格，请确认已进入广告数据面板'
  });
})();

extension\\feishu\\bitable.js.content:
/**
 * 飞书多维表格写入
 * - 写入前拉取表字段，按别名映射真实列名
 * - 只写表里存在的字段，避免 FieldNameNotFound
 */

import {
  BITABLE_FIELD_ALIASES,
  BITABLE_FIELDS,
  BITABLE_REQUIRED_KEYS,
  FEISHU
} from '../lib/constants.js';
import { getConfig } from '../lib/storage.js';
import { getTenantAccessToken } from './auth.js';

/** @type {{ key: string, appToken: string, tableId: string, map: Record<string, {name:string,type:number}>, names: string[], at: number } | null} */
let fieldCache = null;
const FIELD_CACHE_TTL = 5 * 60 * 1000;

/**
 * 业务记录 → 飞书 fields（使用固定首选名；实际写入走 resolve）
 * @param {object} row
 * @param {Record<string, {name:string,type:number}>} [resolvedMap]
 */
export function toBitableFields(row, resolvedMap) {
  const dateMs = row.date ? new Date(`${row.date}T00:00:00`).getTime() : Date.now();
  const scrapedMs = row.scrapedAt ? new Date(row.scrapedAt).getTime() : Date.now();

  const planLabel =
    row.planStatus === 'on'
      ? '投放中'
      : row.planStatus === 'off'
        ? '已关闭'
        : row.planStatus
          ? row.planStatus === 'unknown'
            ? '未知'
            : String(row.planStatus)
          : '';

  const logical = {
    date: dateMs,
    store: row.store || '',
    storeId: row.storeId || '',
    campaign: row.campaign || '',
    spend: Number(row.spend) || 0,
    orders: Number(row.orders) || 0,
    roi: Number(row.roi) || 0,
    revenue: Number(row.revenue) || 0,
    scrapedAt: scrapedMs,
    sourceUrl: row.sourceUrl || '',
    status: row.status || 'success',
    planStatus: planLabel
  };

  // 无映射时用默认中文名（兼容旧逻辑）
  if (!resolvedMap) {
    const out = {};
    for (const [k, v] of Object.entries(logical)) {
      const name = BITABLE_FIELDS[k];
      if (name) out[name] = v;
    }
    return out;
  }

  const out = {};
  for (const [k, v] of Object.entries(logical)) {
    const meta = resolvedMap[k];
    if (!meta?.name) continue;
    out[meta.name] = coerceValue(v, meta.type);
  }
  return out;
}

/**
 * @param {unknown} value
 * @param {number} type 飞书字段 type
 */
function coerceValue(value, type) {
  // 1 text, 3 single select, 4 multi, 15 url → string
  // 2 number → number
  // 5 datetime → ms
  if (type === 2) {
    const n = Number(value);
    return Number.isFinite(n) ? n : 0;
  }
  if (type === 5) {
    if (typeof value === 'number') return value;
    const t = new Date(value).getTime();
    return Number.isFinite(t) ? t : Date.now();
  }
  if (type === 3) {
    // 单选：传选项名字符串
    return String(value ?? '');
  }
  return value == null ? '' : String(value);
}

/**
 * 拉取表字段并解析逻辑字段 → 真实字段名
 */
export async function resolveFieldMap(appToken, tableId, force = false) {
  if (
    !force &&
    fieldCache &&
    fieldCache.appToken === appToken &&
    fieldCache.tableId === tableId &&
    Date.now() - fieldCache.at < FIELD_CACHE_TTL
  ) {
    return fieldCache;
  }

  const token = await getTenantAccessToken();
  const url = `${FEISHU.BITABLE_FIELDS(appToken, tableId)}?page_size=100`;
  const res = await fetch(url, {
    headers: { Authorization: `Bearer ${token}` }
  });
  const json = await res.json().catch(() => ({}));
  if (json.code !== 0) {
    throw new Error(
      `读取飞书表字段失败: code=${json.code} msg=${json.msg}。请确认 App Token / Table ID 正确，且应用已加入该多维表格。`
    );
  }

  const items = json.data?.items || [];
  const names = items.map((f) => f.field_name).filter(Boolean);
  const byName = {};
  for (const f of items) {
    if (f.field_name) byName[f.field_name] = f;
  }

  /** @type {Record<string, {name:string,type:number}>} */
  const map = {};
  for (const [key, aliases] of Object.entries(BITABLE_FIELD_ALIASES)) {
    for (const alias of aliases) {
      if (byName[alias]) {
        map[key] = { name: alias, type: byName[alias].type };
        break;
      }
    }
    // 大小写不敏感兜底
    if (!map[key]) {
      const lowerHit = names.find((n) =>
        aliases.some((a) => a.toLowerCase() === String(n).toLowerCase())
      );
      if (lowerHit && byName[lowerHit]) {
        map[key] = { name: lowerHit, type: byName[lowerHit].type };
      }
    }
  }

  const missingRequired = BITABLE_REQUIRED_KEYS.filter((k) => !map[k]);
  if (missingRequired.length) {
    const need = missingRequired
      .map((k) => `${k}(${(BITABLE_FIELD_ALIASES[k] || []).join('/')})`)
      .join('、');
    throw new Error(
      `飞书表缺少必要字段: ${need}。当前表字段: [${names.join(', ')}]。请补齐列名或改回与文档一致。`
    );
  }

  fieldCache = {
    key: `${appToken}/${tableId}`,
    appToken,
    tableId,
    map,
    names,
    at: Date.now()
  };
  return fieldCache;
}

/**
 * @param {object[]} rows 归一化后的业务行
 * @param {{dryRun?: boolean}} [opts]
 */
export async function writeRecords(rows, opts = {}) {
  const config = await getConfig();
  const { appToken, tableId } = config.feishu || {};
  if (!appToken || !tableId) {
    throw new Error('请先配置飞书多维表格 app_token 与 table_id');
  }

  if (!rows?.length) {
    return { written: 0, batches: 0, dryRun: !!opts.dryRun };
  }

  if (opts.dryRun || config.dryRun) {
    return {
      written: 0,
      batches: 0,
      dryRun: true,
      preview: rows.slice(0, 50)
    };
  }

  const resolved = await resolveFieldMap(appToken, tableId);
  const records = rows.map((r) => ({
    fields: toBitableFields(r, resolved.map)
  }));

  let written = 0;
  let batches = 0;

  for (let i = 0; i < records.length; i += FEISHU.BATCH_SIZE) {
    const chunk = records.slice(i, i + FEISHU.BATCH_SIZE);
    try {
      await batchCreateWithRetry(appToken, tableId, chunk);
    } catch (e) {
      // 字段可能刚改过，清缓存重解析一次再试
      if (/1254045|FieldNameNotFound/i.test(String(e.message || e))) {
        fieldCache = null;
        const again = await resolveFieldMap(appToken, tableId, true);
        const retryChunk = rows.slice(i, i + FEISHU.BATCH_SIZE).map((r) => ({
          fields: toBitableFields(r, again.map)
        }));
        try {
          await batchCreateWithRetry(appToken, tableId, retryChunk);
        } catch (e2) {
          throw enhanceFieldError(e2, again.names, again.map);
        }
      } else {
        throw enhanceFieldError(e, resolved.names, resolved.map);
      }
    }
    written += chunk.length;
    batches += 1;
  }

  return {
    written,
    batches,
    dryRun: false,
    fieldMap: Object.fromEntries(
      Object.entries(resolved.map).map(([k, v]) => [k, v.name])
    )
  };
}

function enhanceFieldError(err, tableNames, map) {
  const msg = String(err.message || err);
  if (!/1254045|FieldNameNotFound/i.test(msg)) return err;
  const used = map ? Object.values(map).map((m) => m.name) : [];
  const hint = new Error(
    `${msg}。写入使用字段: [${used.join(', ')}]，表内字段: [${(tableNames || []).join(', ')}]。请检查插件设置的 Table ID 是否指向当前表，并重新加载插件 v1.0.3+。`
  );
  hint.status = err.status;
  hint.body = err.body;
  return hint;
}

async function batchCreateWithRetry(appToken, tableId, records) {
  let lastErr;
  for (let attempt = 0; attempt < FEISHU.MAX_RETRIES; attempt++) {
    try {
      return await batchCreate(appToken, tableId, records, attempt > 0);
    } catch (e) {
      lastErr = e;
      const msg = String(e.message || e);
      // 字段不存在：不要无意义重试多次
      if (/1254045|FieldNameNotFound/i.test(msg)) throw e;
      if (/99991663|99991661|token/i.test(msg) || e.status === 401) {
        await getTenantAccessToken(true);
      }
      const delay = Math.min(1000 * 2 ** attempt, 8000);
      await sleep(delay);
    }
  }
  throw lastErr;
}

async function batchCreate(appToken, tableId, records, forceToken = false) {
  const token = await getTenantAccessToken(forceToken);
  const url = FEISHU.BITABLE_BATCH_CREATE(appToken, tableId);
  const res = await fetch(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json; charset=utf-8'
    },
    body: JSON.stringify({ records })
  });

  const json = await res.json().catch(() => ({}));
  if (!res.ok || json.code !== 0) {
    const err = new Error(
      `飞书写入失败: HTTP ${res.status} code=${json.code} msg=${json.msg || JSON.stringify(json)}`
    );
    err.status = res.status;
    err.body = json;
    throw err;
  }
  return json;
}

/**
 * 测试飞书连通性：拿 token + 读字段 + 读 1 条记录
 */
export async function testFeishuConnection() {
  const config = await getConfig();
  const { appToken, tableId } = config.feishu || {};
  if (!appToken || !tableId) {
    throw new Error('缺少 app_token 或 table_id');
  }
  const token = await getTenantAccessToken(true);
  const resolved = await resolveFieldMap(appToken, tableId, true);
  const url = `${FEISHU.BITABLE_LIST(appToken, tableId)}?page_size=1`;
  const res = await fetch(url, {
    headers: { Authorization: `Bearer ${token}` }
  });
  const json = await res.json();
  if (json.code !== 0) {
